var EXTRA=[{dot:"gray",j:"Sports Health",h:"Dopo la rottura del LCA il cammino cambia su entrambe le gambe",v:"Studio cinese-britannico su 22 pazienti recenti e 18 controlli: anche l'arto non operato cambia rotazione di anca e caviglia durante il cammino, non solo quello infortunato.",pmid:'42725479',doi:'10.1177/19417381261479683',temi:["lca","biomeccanica del cammino","compenso bilaterale"]},{dot:"gray",j:"Arthroscopy, Sports Medicine, and Rehabilitation",h:"Un condilo femorale mediale stretto aumenta l'instabilita rotatoria dopo il LCA",v:"Coorte cinese di 141 pazienti: chi ha un condilo femorale mediale piu stretto rischia di piu l'instabilita rotatoria anteromediale, spesso insieme a lesioni del collaterale mediale profondo.",pmid:'42724688',doi:'10.1002/ars2.70073',temi:["lca","instabilita rotatoria","anatomia ossea"]},{dot:"gray",j:"Research in Sports Medicine",h:"Nei calciatori professionisti una tacca intercondiloidea stretta si associa alla rottura del LCA",v:"Studio caso-controllo turco su 81 calciatori: un indice di larghezza della tacca piu basso si associa alla rottura non da contatto del LCA, mentre lo slope tibiale non fa differenza in questa popolazione.",pmid:'42723232',doi:'10.1080/15438627.2026.2730383',temi:["lca","calciatori","fattori di rischio anatomici"]},{dot:"green",j:"Journal of Experimental Orthopaedics",h:"Una tecnica a paracadute fissa bene i frammenti osteocondrali dopo lussazione di rotula",v:"Serie tedesca di 20 pazienti: la refissazione del frammento osteocondrale con suture transpatellari, insieme alla ricostruzione dell'MPFL, da buona integrazione alla RM e alta soddisfazione a 5 anni di follow-up medio.",pmid:'42719315',doi:'10.1002/jeo2.70894',temi:["rotula","cartilagine","instabilita rotulea"]},{dot:"gray",j:"JAC-Antimicrobial Resistance",h:"I germi Gram-negativi nell'infezione protesica cambiano la scelta dell'antibiotico empirico",v:"Coorte retrospettiva su infezioni protesiche di anca e ginocchio: identifica i fattori di rischio per un'eziologia Gram-negativa, rilevante per la terapia antibiotica empirica prima dell'antibiogramma.",pmid:'42724465',doi:'10.1093/jacamr/dlag206',temi:["protesi totale","infezione","antibiotici"]},{dot:"gray",j:"Frontiers in Surgery",h:"Una frattura di rotula puo ridislocarsi nel paziente con Parkinson",v:"Caso clinico e rassegna della letteratura: il tremore e la rigidita del Parkinson complicano la tenuta della sintesi a cerchiaggio nella frattura di rotula, con ridislocazione post-operatoria.",pmid:'42723749',doi:'10.3389/fsurg.2026.1791697',temi:["frattura di rotula","traumatologia","malattia di Parkinson"]},{dot:"gray",j:"JBJS Case Connector",h:"Osteotomia femorale e MPFL insieme in un raro caso di esostosi multiple ereditarie",v:"Caso clinico: instabilita rotulea da deformita ossea in un paziente con esostosi multiple ereditarie, trattata con osteotomia distale femorale e ricostruzione del legamento patello-femorale mediale nello stesso tempo chirurgico.",pmid:'42721308',doi:'10.2106/JBJS.CC.26.00166',temi:["rotula","osteotomia","malattia rara"]},{dot:"gray",j:"JBJS Case Connector",h:"Una cisti di Baker dopo protesi di ginocchio trattata per via artroscopica posteromediale",v:"Caso clinico: una cisti di Baker sintomatica comparsa dopo protesi totale di ginocchio, risolta con un accesso artroscopico posteromediale dedicato invece della chirurgia aperta classica.",pmid:'42721365',doi:'10.2106/JBJS.CC.26.00217',temi:["protesi totale","cisti di Baker","artroscopia"]},{dot:"gray",j:"Frontiers in Surgery",h:"La vitamina D bassa potrebbe pesare sulla trombosi dopo la protesi di ginocchio",v:"Analisi retrospettiva che genera un'ipotesi: livelli piu bassi di vitamina D prima della protesi di ginocchio si associano a trombosi venosa profonda, con un meccanismo di coagulazione ancora da dimostrare.",pmid:'42723925',doi:'10.3389/fsurg.2026.1756540',temi:["protesi totale","trombosi","vitamina D"]},{dot:"gray",j:"Physical Therapy in Sport",h:"Il dibattito su riabilitazione da sola o ricostruzione del LCA continua",v:"Una lettera all'editore commenta lo studio di coorte svedese NACOX sul rientro allo sport dopo trattamento conservativo o ricostruzione del LCA: la discussione metodologica resta aperta.",pmid:'42728205',doi:'10.1016/j.ptsp.2026.101991',temi:["lca","trattamento conservativo","dibattito scientifico"]},{dot:"gray",j:"Physiotherapy Research International",h:"Il taping della caviglia cambia anche la biomeccanica del ginocchio nell'atterraggio",v:"Studio trasversale su soggetti sani: diversi tipi di taping preventivo della caviglia modificano in modo misurabile la meccanica del ginocchio durante compiti di atterraggio da salto.",pmid:'42717845',doi:'10.1002/pri.70335',temi:["prevenzione infortuni","biomeccanica","atterraggio"]},{dot:"gray",j:"The Knee",h:"I chatbot rispondono bene, ma non benissimo, sulle domande dei pazienti sulla protesi robotica",v:"Confronto fra quattro assistenti di intelligenza artificiale su trenta domande frequenti sulla protesi di ginocchio robot-assistita: accuratezza clinica accettabile, ma leggibilita sopra il livello raccomandato per i pazienti.",pmid:'42727207',doi:'10.1016/j.knee.2026.104635',temi:["intelligenza artificiale","protesi robotica","informazione al paziente"]}];
var SCOPERTE=[{t:"In Cina, un sensore nella scarpa prova a leggere l'artrosi dal modo in cui cammini",v:"Un gruppo di ingegneria di Guangzhou ha addestrato un modello che combina la pressione plantare misurata da un plantare sensorizzato con un indice di coordinazione del passo per riconoscere l'artrosi radiografica di ginocchio. Su un campione di soli 92 partecipanti l'accuratezza e incoraggiante ma gli stessi autori dichiarano intervalli di confidenza ampi e la necessita di una validazione multicentrica prima di pensarlo come strumento clinico di monitoraggio.",pmid:'42726790',doi:'10.2196/101026',temi:["intelligenza artificiale","sensori indossabili","mondo orientale"]},{t:"Un esoscheletro del ginocchio, e il problema e allinearlo bene con l'articolazione vera",v:"Uno studio di ingegneria misura quanto un disallineamento dell'asse di rotazione fra un esoscheletro del ginocchio e l'articolazione naturale cambi la coppia trasmessa all'arto umano. Lontano dalla sala operatoria, ma un promemoria concreto — utile anche per chi pensa alla robotica indossabile in riabilitazione — che nella robotica applicata al ginocchio la precisione meccanica del contatto uomo-macchina non e un dettaglio.",pmid:'42655429',doi:'10.3390/s26165119',temi:["esoscheletro","bioingegneria","robotica indossabile"]},{t:"Sferoidi di cartilagine coltivati in laboratorio, non ancora per il tuo ambulatorio",v:"Un gruppo svizzero descrive come ingegnerizzare sferoidi di condroprogenitori allogenici — cellule da donatore, non del paziente — per riempire grandi difetti cartilaginei, con l'obiettivo dichiarato di un giorno arrivare a una produzione conforme agli standard farmaceutici (GMP). E ricerca preclinica su microambiente e formulazione, agli antipodi tecnologici dell'AMIC e dell'AutoCart che usi tu, ma nella stessa direzione: cartilagine che ripara cartilagine.",pmid:'42654149',doi:'10.3390/pharmaceutics18081032',temi:["cartilagine","terapia cellulare","bioingegneria"]}];
var SOC={"1": {"video": "Per ricostruire il legamento crociato anteriore si possono usare tendini diversi, e diversi studi randomizzati hanno confrontato due delle scelte piu comuni trovando risultati sostanzialmente simili. Una nuova analisi statistica ha voluto controllare se questa somiglianza fosse un dato solido oppure un'apparenza dovuta al caso o a pazienti persi durante lo studio. La verifica, condotta su otto studi e oltre cinquecento pazienti, conferma che la somiglianza tra i due innesti e reale e stabile: anche simulando che alcuni pazienti avessero avuto un risultato diverso da quello osservato, la conclusione di fondo non cambia. È un tipo di controllo statistico pensato apposta per distinguere un risultato affidabile da uno fragile. Un limite importante: nessuno di questi otto studi includeva un ulteriore gesto chirurgico di rinforzo che spesso si esegue insieme alla ricostruzione, quindi il confronto vale per il solo tipo di tendine usato, non per la combinazione completa di tecniche. Resta comunque un buon argomento a favore dell'equivalenza fra le due scelte di innesto sul piano dei risultati a breve termine."}, "2": {"video": "Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo, non solo al ginocchio. Uno studio ha riunito i dati di tredici ricerche precedenti, quasi quattromila pazienti in tutto, per capire se questa caratteristica influenzi i risultati dopo la ricostruzione del legamento crociato anteriore. Il risultato mostra che questi pazienti tendono ad avere punteggi di funzione del ginocchio un po' piu bassi dopo l'intervento, e segni clinici di lassita residua piu frequenti al controllo del chirurgo. Sul rischio di dover rifare l'intervento, invece, il dato numerico va nella stessa direzione ma non e abbastanza solido da essere certo. Questo significa che, con le informazioni disponibili oggi, non si puo dire con sicurezza se il rischio di reintervento sia davvero piu alto in queste persone. E comunque un'informazione utile da conoscere e discutere prima dell'operazione, per capire cosa aspettarsi nel percorso di recupero."}, "3": {"video": "Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri preferiscono prima un periodo di riabilitazione e valutano l'intervento in un secondo momento. Una revisione di undici studi, con oltre novemilacinquecento pazienti in totale, ha confrontato cosa succede scegliendo l'una o l'altra strada. Il dato piu solido riguarda il menisco, la struttura cartilaginea a forma di mezzaluna dentro il ginocchio: chi opera entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco rispetto a chi aspetta di piu. Sulla funzione generale del ginocchio, invece, le due strategie sembrano equivalersi. Va detto che questi sono tutti studi osservativi, non esperimenti controllati: chi arriva tardi all'intervento potrebbe avere altre caratteristiche che spiegano il maggior danno al menisco, non necessariamente solo il tempo trascorso. Ma il messaggio pratico resta utile: non c'e un grande vantaggio ad aspettare troppo, soprattutto per il menisco."}, "4": {"video": "Per decidere quando un atleta puo tornare a giocare dopo l'intervento al legamento crociato anteriore, il test piu usato confronta la forza delle due gambe: se sono abbastanza simili, si da il via libera. Uno studio su centoventisette atleti professionisti ha verificato se questo test funzioni davvero bene per prevedere chi si fara male di nuovo. Il risultato mostra che questo confronto di forza, da solo, predice poco il rischio di reinfortunio. Molto piu collegata al rischio e invece la prontezza psicologica dell'atleta, cioe quanto si sente sicuro e pronto mentalmente a tornare a livelli intensi di gioco, misurata con un questionario apposito. Lo studio ha seguito un numero limitato di atleti che si sono davvero reinfortunati, quindi il dato va confermato con ricerche piu ampie. Ma suggerisce che, nel percorso di rientro, la componente psicologica meriti la stessa attenzione data ai test fisici."}, "5": {"video": "Dopo l'intervento al legamento crociato anteriore, il muscolo davanti alla coscia — il quadricipite — spesso resta piu debole per diversi mesi. Uno studio ha seguito cinquantanove pazienti per un anno intero, guardando sia quanta forza recuperavano sia come camminavano nel tempo. I pazienti che recuperano meno forza continuano a camminare in modo un po' diverso anche dopo un anno, con un ginocchio che si piega meno durante il passo — un pattern che altri studi collegano al rischio di artrosi negli anni successivi. Chi recupera piu forza cammina meglio, ma nemmeno in questo caso il cammino torna del tutto come prima dell'infortunio. Il messaggio pratico e che rinforzare il quadricipite dopo l'intervento resta fondamentale, ma potrebbe non bastare da solo: potrebbe servire un lavoro specifico anche sul modo di camminare, non solo sulla forza muscolare misurata in palestra."}, "6": {"video": "Quando un chirurgo deve decidere se e come correggere l'asse di una gamba storta, di solito guarda a un unico numero che riassume l'allineamento complessivo. Uno studio coreano ha seguito oltre settecento ginocchia per piu di dieci anni, scomponendo questo numero nei due angoli separati — quello del femore e quello della tibia — per vedere se la loro combinazione specifica facesse la differenza. E emerso che certe combinazioni di questi due angoli aumentano molto il rischio che l'artrosi peggiori nel tempo, anche quando l'angolo complessivo della gamba sembrerebbe normale. In pratica, due gambe che sembrano allineate allo stesso modo possono nascondere rischi diversi a seconda di come e distribuito quell'allineamento fra femore e tibia. Lo studio guarda al passato, non e un esperimento controllato, e alcuni gruppi analizzati sono piccoli. Ma suggerisce che, quando si pianifica un intervento di correzione, vale la pena guardare oltre il solo numero complessivo dell'allineamento della gamba."}, "7": {"video": "La protesi di ginocchio con l'aiuto del robot promette di essere piu precisa della tecnica manuale classica. Uno studio su quattrocentotrenta pazienti ha confrontato le due tecniche nel tempo, guardando anche a un aspetto interessante: se l'esperienza del chirurgo che opera faccia la differenza. Nei primi tre mesi dopo l'intervento, chi e stato operato con il robot ha punteggi di recupero leggermente migliori, ma questo vantaggio si riduce col tempo e sparisce del tutto a un anno di distanza. Il dato piu curioso: il beneficio del robot nei primi mesi e maggiore proprio quando a operare e un chirurgo con meno esperienza, che con il robot ottiene risultati vicini a quelli di un collega piu esperto. Questa parte dello studio sull'esperienza del chirurgo non era stata pianificata all'inizio, quindi va confermata con altre ricerche. Ma suggerisce che il robot possa aiutare soprattutto a livellare i risultati fra chirurghi diversi, piu che a migliorare il risultato finale in assoluto."}, "8": {"video": "Semaglutide e tirzepatide sono due farmaci per il diabete sempre piu diffusi, anche fra chi si prepara a un intervento di protesi di ginocchio. Uno studio su un ampio database sanitario ha confrontato la sicurezza dei due farmaci nel periodo intorno all'intervento, su oltre ottocento pazienti diabetici. Il risultato e rassicurante: non emergono differenze importanti fra i due farmaci sulle complicanze mediche o chirurgiche nei mesi successivi all'operazione, ne su eventi specifici come le infezioni o le visite in pronto soccorso. Va detto che alcuni di questi eventi sono comunque rari, quindi i numeri restano un po' imprecisi e non permettono di escludere del tutto piccole differenze fra i due farmaci. Ma il messaggio di fondo e che nessuno dei due sembra da preferire per motivi di sicurezza chirurgica."}, "9": {"video": "Quando si ripara il menisco durante un'artroscopia, si possono usare diversi tipi di dispositivi per fissare il punto di sutura: alcuni consistono in un filo che si annoda da solo, altri in una piccola ancora rigida che puo lasciare o no un nodo a contatto con il menisco. Un commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi. Dall'analisi emerge che i dispositivi con ancora rigida senza nodo a contatto con il menisco sembrano avere meno segnalazioni di problemi rispetto agli altri due tipi. Viene anche segnalato che non tutte le aziende produttrici segnalano i problemi con la stessa rapidita. Il commento non permette di indicare quale marca specifica sia coinvolta, e non e uno studio con la propria analisi statistica indipendente. Ma e un promemoria utile che i dettagli tecnici del dispositivo usato per riparare il menisco possono fare la differenza, non solo la bravura del chirurgo."}};
var SOCV={"1": {"video": {"chir": ["Otto studi randomizzati hanno confrontato l'innesto di tendine hamstring e quello di tendine quadricipitale nella ricostruzione del legamento crociato anteriore, trovando esiti a breve termine comparabili fra i due. Una nuova analisi ha voluto verificare se questa conclusione fosse statisticamente solida o fragile, calcolando quanti pazienti dovrebbero cambiare risultato prima che la non-differenza diventi una differenza significativa.", "Il risultato: l'indice di fragilita medio calcolato sui 562 pazienti allocati e su 482 disponibili al follow-up e di 17,4, sempre superiore al numero di pazienti effettivamente persi durante gli studi. In pratica, la conclusione «risultati comparabili» non dipende da un caso statistico fortunato: regge anche simulando scenari sfavorevoli, con stime confermate stabili su venti simulazioni indipendenti.", "Il limite riguarda proprio l'uso che se ne puo fare nella pratica quotidiana con il rinforzo laterale: nessuno degli otto studi randomizzati includeva quella combinazione, quindi questa robustezza vale per l'innesto preso da solo. Rafforza comunque, sul piano metodologico, la scelta del tendine quadricipitale rispetto all'hamstring come base di partenza dell'intervento."], "misto": ["Per ricostruire il legamento crociato anteriore si possono usare tendini diversi, e diversi studi randomizzati hanno confrontato due delle scelte piu comuni trovando risultati sostanzialmente simili. Una nuova analisi statistica ha voluto controllare se questa somiglianza fosse un dato solido oppure un'apparenza dovuta al caso o a pazienti persi durante lo studio.", "La verifica, condotta su otto studi e oltre cinquecento pazienti, conferma che la somiglianza tra i due innesti e reale e stabile: anche simulando che alcuni pazienti avessero avuto un risultato diverso da quello osservato, la conclusione di fondo non cambia. È un tipo di controllo statistico pensato apposta per distinguere un risultato affidabile da uno fragile.", "Un limite importante: nessuno di questi otto studi includeva un ulteriore gesto chirurgico di rinforzo che spesso si esegue insieme alla ricostruzione, quindi il confronto vale per il solo tipo di tendine usato, non per la combinazione completa di tecniche. Resta comunque un buon argomento a favore dell'equivalenza fra le due scelte di innesto sul piano dei risultati a breve termine."], "pazienti": ["Quando si ricostruisce il legamento crociato del ginocchio, si puo scegliere fra tipi diversi di tendine da usare come nuovo legamento. Diversi studi avevano gia mostrato che due di queste scelte danno risultati simili, ma una nuova analisi ha voluto controllare se questa somiglianza fosse davvero affidabile.", "Il controllo, molto rigoroso dal punto di vista statistico, conferma che si': i risultati simili osservati negli studi non sono un caso, ma un dato solido su cui si puo fare affidamento quando si discute con il chirurgo quale tendine scegliere.", "Va detto che questi studi non includevano un ulteriore piccolo intervento di rinforzo che alcuni chirurghi eseguono insieme alla ricostruzione principale: il confronto riguarda quindi solo la scelta del tendine, non l'intervento completo. Ma per orientarsi fra le due opzioni piu comuni, e un'informazione rassicurante."]}, "linkedin": {"chir": ["Rianalisi di fragilita: la non-differenza fra hamstring e quadricipite regge", "Otto RCT, 562 pazienti: l'indice di fragilita continua inversa (media 17,4) mostra che gli esiti continui non significativi fra i due innesti nel LCA sono statisticamente robusti, non un artefatto della perdita al follow-up.", "Nessuno degli 8 RCT include il rinforzo laterale (LET): la robustezza riguarda l'innesto isolato, non la combinazione che si esegue di routine.\n\nTseng, Fu, Lo et al., Orthopaedic Journal of Sports Medicine, settembre 2026."], "misto": ["Tendine del ginocchio o tendine del quadricipite: la scienza dice davvero che sono uguali?", "Una nuova analisi statistica ha riesaminato otto studi randomizzati che confrontano due tipi di innesto per ricostruire il legamento crociato anteriore, e ha verificato se la conclusione «risultati simili» fosse solida o fragile.", "Il risultato conferma che la conclusione regge: i due innesti danno esiti a breve termine davvero comparabili, non un'apparenza statistica dovuta a pazienti persi durante lo studio.\n\nTseng, Fu, Lo et al., Orthopaedic Journal of Sports Medicine, settembre 2026."], "pazienti": ["Due tendini diversi per ricostruire il legamento del ginocchio, con risultati simili: uno studio lo conferma", "Per ricostruire il legamento crociato anteriore si possono usare tendini diversi. Una nuova analisi ha riesaminato otto studi scientifici che confrontano due di queste scelte, per capire se i risultati simili osservati fossero davvero affidabili.", "La conferma c'e: a breve termine i risultati restano confrontabili fra le due tecniche, un'informazione utile per il colloquio prima dell'intervento sulla scelta dell'innesto.\n\nTseng, Fu, Lo et al., Orthopaedic Journal of Sports Medicine, settembre 2026."]}, "instagram": {"chir": ["Tendine quadricipite o hamstring: la non-differenza regge alla prova\nRianalisi di fragilita: la non-differenza fra hamstring e quadricipite regge", "Otto RCT, 562 pazienti: l'indice di fragilita continua inversa (media 17,4) mostra che gli esiti continui non significativi fra i due innesti nel LCA sono statisticamente robusti, non un artefatto della perdita al follow-up.", "Nessuno degli 8 RCT include il rinforzo laterale (LET): la robustezza riguarda l'innesto isolato, non la combinazione che si esegue di routine."], "misto": ["Tendine quadricipite o hamstring: la non-differenza regge alla prova\nTendine del ginocchio o tendine del quadricipite: la scienza dice davvero che sono uguali?", "Una nuova analisi statistica ha riesaminato otto studi randomizzati che confrontano due tipi di innesto per ricostruire il legamento crociato anteriore, e ha verificato se la conclusione «risultati simili» fosse solida o fragile.", "Il risultato conferma che la conclusione regge: i due innesti danno esiti a breve termine davvero comparabili, non un'apparenza statistica dovuta a pazienti persi durante lo studio."], "pazienti": ["Tendine quadricipite o hamstring: la non-differenza regge alla prova\nDue tendini diversi per ricostruire il legamento del ginocchio, con risultati simili: uno studio lo conferma", "Per ricostruire il legamento crociato anteriore si possono usare tendini diversi.\nUna nuova analisi ha riesaminato otto studi scientifici che confrontano due di queste scelte, per capire se i risultati simili osservati fossero davvero affidabili.", "La conferma c'e: a breve termine i risultati restano confrontabili fra le due tecniche, un'informazione utile per il colloquio prima dell'intervento sulla scelta dell'innesto."]}, "reel": {"chir": ["[IL DATO] Rianalisi di fragilita: la non-differenza fra hamstring e quadricipite regge", "[COSA SIGNIFICA] Otto RCT, 562 pazienti: l'indice di fragilita continua inversa (media 17,4) mostra che gli esiti continui non significativi fra i due innesti nel LCA sono statisticamente robusti, non un artefatto della perdita al follow-up.", "[IL LIMITE] Nessuno degli 8 RCT include il rinforzo laterale (LET): la robustezza riguarda l'innesto isolato, non la combinazione che si esegue di routine."], "misto": ["[COSA DICE LO STUDIO] Tendine del ginocchio o tendine del quadricipite: la scienza dice davvero che sono uguali?", "[PERCHE CONTA] Una nuova analisi statistica ha riesaminato otto studi randomizzati che confrontano due tipi di innesto per ricostruire il legamento crociato anteriore, e ha verificato se la conclusione «risultati simili» fosse solida o fragile.", "[IL LIMITE] Il risultato conferma che la conclusione regge: i due innesti danno esiti a breve termine davvero comparabili, non un'apparenza statistica dovuta a pazienti persi durante lo studio."], "pazienti": ["[COSA DICE LO STUDIO] Due tendini diversi per ricostruire il legamento del ginocchio, con risultati simili: uno studio lo conferma", "[COSA CAMBIA PER TE] Per ricostruire il legamento crociato anteriore si possono usare tendini diversi. Una nuova analisi ha riesaminato otto studi scientifici che confrontano due di queste scelte, per capire se i risultati simili osservati fossero davvero affidabili.", "[IL LIMITE] La conferma c'e: a breve termine i risultati restano confrontabili fra le due tecniche, un'informazione utile per il colloquio prima dell'intervento sulla scelta dell'innesto."]}}, "2": {"video": {"chir": ["Una meta-analisi ha riunito tredici studi e quasi quattromila pazienti sottoposti a ricostruzione del legamento crociato anteriore, per capire se avere articolazioni naturalmente piu lasse in tutto il corpo — la cosiddetta lassita articolare generalizzata — cambi i risultati dell'intervento rispetto a chi non ce l'ha.", "I punteggi funzionali IKDC e Lysholm risultano significativamente piu bassi nei pazienti con lassita generalizzata, e i segni clinici di lassita residua al ginocchio — test di Lachman e pivot shift positivi — sono circa due volte piu frequenti. Sul tasso di fallimento dell'innesto la differenza numerica esiste, quasi il doppio, ma non raggiunge la significativita statistica.", "Il limite e proprio li: l'odds ratio di 3,15 sul fallimento e riportato senza intervallo di confidenza, quindi non si puo escludere ne un rischio davvero piu alto ne l'assenza di un vero effetto. Un profilo di rischio da tenere presente nel colloquio pre-operatorio con questi pazienti, indipendentemente dal tipo di innesto scelto."], "misto": ["Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo, non solo al ginocchio. Uno studio ha riunito i dati di tredici ricerche precedenti, quasi quattromila pazienti in tutto, per capire se questa caratteristica influenzi i risultati dopo la ricostruzione del legamento crociato anteriore.", "Il risultato mostra che questi pazienti tendono ad avere punteggi di funzione del ginocchio un po' piu bassi dopo l'intervento, e segni clinici di lassita residua piu frequenti al controllo del chirurgo. Sul rischio di dover rifare l'intervento, invece, il dato numerico va nella stessa direzione ma non e abbastanza solido da essere certo.", "Questo significa che, con le informazioni disponibili oggi, non si puo dire con sicurezza se il rischio di reintervento sia davvero piu alto in queste persone. E comunque un'informazione utile da conoscere e discutere prima dell'operazione, per capire cosa aspettarsi nel percorso di recupero."], "pazienti": ["Se le tue articolazioni sono naturalmente piu mobili del normale — non solo al ginocchio, ma in generale — questo puo avere un piccolo effetto sui risultati dopo l'intervento per il legamento crociato anteriore, come mostra uno studio che ha messo insieme i dati di quasi quattromila persone operate.", "In queste persone il ginocchio tende a restare un po' piu «morbido» anche dopo l'intervento, e i punteggi di recupero funzionale sono leggermente inferiori rispetto a chi non ha questa caratteristica. Non e chiaro invece se il rischio di dover rifare l'operazione sia davvero maggiore.", "E un'informazione da conoscere, non un motivo di allarme: se il tuo chirurgo nota che le tue articolazioni sono particolarmente mobili, ne terra conto nel programmare la riabilitazione e nello spiegarti cosa aspettarti dal recupero."]}, "linkedin": {"chir": ["Nella lassita articolare generalizzata, piu lassita residua dopo il LCA", "Meta-analisi di 13 studi, 3905 pazienti: IKDC e Lysholm significativamente piu bassi, Lachman e pivot shift piu spesso positivi in chi ha lassita generalizzata, senza differenza certa nel tasso di fallimento (OR 3,15; p=0,07, IC non riportato).", "L'assenza di significativita sul fallimento non e una dimostrazione di equivalenza: con un OR di 3,15 senza intervallo di confidenza, il dato resta impreciso.\n\nZa, Papalia, Caria et al., Knee Surg Sports Traumatol Arthrosc, settembre 2026."], "misto": ["Ginocchia piu «elastiche»: cosa cambia dopo la ricostruzione del legamento crociato", "Uno studio ha riunito i dati di quasi 4000 pazienti per capire se avere articolazioni naturalmente piu lasse in tutto il corpo influisca sui risultati dopo la ricostruzione del crociato anteriore.", "I punteggi funzionali risultano un po' piu bassi e i segni clinici di lassita piu frequenti in questi pazienti, mentre non e chiaro se il rischio di dover rioperare sia davvero piu alto: il numero disponibile non basta a dirlo con certezza.\n\nZa, Papalia, Caria et al., Knee Surg Sports Traumatol Arthrosc, settembre 2026."], "pazienti": ["Se le tue articolazioni sono naturalmente piu «elastiche», il crociato va seguito con attenzione in piu", "Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo. Uno studio su quasi 4000 pazienti ha verificato se questo influisce sui risultati dopo l'intervento per il legamento crociato del ginocchio.", "Chi ha questa caratteristica tende ad avere un ginocchio un po' piu lasso anche dopo l'intervento, con punteggi di funzione leggermente inferiori. Non e chiaro se il rischio di un secondo intervento sia davvero maggiore: serve prudenza nel trarre conclusioni definitive.\n\nZa, Papalia, Caria et al., Knee Surg Sports Traumatol Arthrosc, settembre 2026."]}, "instagram": {"chir": ["La lassita articolare generalizzata pesa dopo la ricostruzione del LCA\nNella lassita articolare generalizzata, piu lassita residua dopo il LCA", "Meta-analisi di 13 studi, 3905 pazienti: IKDC e Lysholm significativamente piu bassi, Lachman e pivot shift piu spesso positivi in chi ha lassita generalizzata, senza differenza certa nel tasso di fallimento (OR 3,15; p=0,07, IC non riportato).", "L'assenza di significativita sul fallimento non e una dimostrazione di equivalenza: con un OR di 3,15 senza intervallo di confidenza, il dato resta impreciso."], "misto": ["La lassita articolare generalizzata pesa dopo la ricostruzione del LCA\nGinocchia piu «elastiche»: cosa cambia dopo la ricostruzione del legamento crociato", "Uno studio ha riunito i dati di quasi 4000 pazienti per capire se avere articolazioni naturalmente piu lasse in tutto il corpo influisca sui risultati dopo la ricostruzione del crociato anteriore.", "I punteggi funzionali risultano un po' piu bassi e i segni clinici di lassita piu frequenti in questi pazienti, mentre non e chiaro se il rischio di dover rioperare sia davvero piu alto: il numero disponibile non basta a dirlo con certezza."], "pazienti": ["La lassita articolare generalizzata pesa dopo la ricostruzione del LCA\nSe le tue articolazioni sono naturalmente piu «elastiche», il crociato va seguito con attenzione in piu", "Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo.\nUno studio su quasi 4000 pazienti ha verificato se questo influisce sui risultati dopo l'intervento per il legamento crociato del ginocchio.", "Chi ha questa caratteristica tende ad avere un ginocchio un po' piu lasso anche dopo l'intervento, con punteggi di funzione leggermente inferiori.\nNon e chiaro se il rischio di un secondo intervento sia davvero maggiore: serve prudenza nel trarre conclusioni definitive."]}, "reel": {"chir": ["[IL DATO] Nella lassita articolare generalizzata, piu lassita residua dopo il LCA", "[COSA SIGNIFICA] Meta-analisi di 13 studi, 3905 pazienti: IKDC e Lysholm significativamente piu bassi, Lachman e pivot shift piu spesso positivi in chi ha lassita generalizzata, senza differenza certa nel tasso di fallimento (OR 3,15; p=0,07, IC non riportato).", "[IL LIMITE] L'assenza di significativita sul fallimento non e una dimostrazione di equivalenza: con un OR di 3,15 senza intervallo di confidenza, il dato resta impreciso."], "misto": ["[COSA DICE LO STUDIO] Ginocchia piu «elastiche»: cosa cambia dopo la ricostruzione del legamento crociato", "[PERCHE CONTA] Uno studio ha riunito i dati di quasi 4000 pazienti per capire se avere articolazioni naturalmente piu lasse in tutto il corpo influisca sui risultati dopo la ricostruzione del crociato anteriore.", "[IL LIMITE] I punteggi funzionali risultano un po' piu bassi e i segni clinici di lassita piu frequenti in questi pazienti, mentre non e chiaro se il rischio di dover rioperare sia davvero piu alto: il numero disponibile non basta a dirlo con certezza."], "pazienti": ["[COSA DICE LO STUDIO] Se le tue articolazioni sono naturalmente piu «elastiche», il crociato va seguito con attenzione in piu", "[COSA CAMBIA PER TE] Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo. Uno studio su quasi 4000 pazienti ha verificato se questo influisce sui risultati dopo l'intervento per il legamento crociato del ginocchio.", "[IL LIMITE] Chi ha questa caratteristica tende ad avere un ginocchio un po' piu lasso anche dopo l'intervento, con punteggi di funzione leggermente inferiori. Non e chiaro se il rischio di un secondo intervento sia davvero maggiore: serve prudenza nel trarre conclusioni definitive."]}}, "3": {"video": {"chir": ["Da anni si discute se sia meglio ricostruire il legamento crociato anteriore subito dopo l'infortunio o aspettare, magari facendo prima un periodo di riabilitazione. Una revisione sistematica ha riunito undici studi, oltre novemilacinquecento pazienti in totale, per confrontare le due strategie su piu fronti: lesioni associate, punteggi funzionali, rientro allo sport.", "Il dato piu chiaro riguarda il menisco: chi ricostruisce entro tre mesi dall'infortunio ha una lesione meniscale associata nel 49,5% dei casi, contro il 59,6% di chi aspetta di piu, soprattutto a carico del menisco mediale. Sui punteggi funzionali riferiti dal paziente, invece, non emerge un vantaggio chiaro per nessuna delle due tempistiche.", "Il limite principale e che tutti gli studi inclusi sono osservazionali, non randomizzati: chi arriva tardi all'intervento potrebbe differire per altri motivi che spiegano anche il danno meniscale maggiore. Resta comunque un argomento in piu, quantificato, per non prolungare inutilmente l'attesa quando la lesione meniscale associata e un rischio concreto."], "misto": ["Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri preferiscono prima un periodo di riabilitazione e valutano l'intervento in un secondo momento. Una revisione di undici studi, con oltre novemilacinquecento pazienti in totale, ha confrontato cosa succede scegliendo l'una o l'altra strada.", "Il dato piu solido riguarda il menisco, la struttura cartilaginea a forma di mezzaluna dentro il ginocchio: chi opera entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco rispetto a chi aspetta di piu. Sulla funzione generale del ginocchio, invece, le due strategie sembrano equivalersi.", "Va detto che questi sono tutti studi osservativi, non esperimenti controllati: chi arriva tardi all'intervento potrebbe avere altre caratteristiche che spiegano il maggior danno al menisco, non necessariamente solo il tempo trascorso. Ma il messaggio pratico resta utile: non c'e un grande vantaggio ad aspettare troppo, soprattutto per il menisco."], "pazienti": ["Dopo la rottura del legamento crociato del ginocchio, alcune persone scelgono di operare subito, altre preferiscono prima fare fisioterapia e decidere piu avanti. Uno studio ha confrontato queste due strade su quasi diecimila pazienti in totale, per capire quale conviene di piu.", "E emerso che chi opera entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco, la piccola struttura a forma di mezzaluna dentro il ginocchio che protegge la cartilagine. Sul recupero generale della funzione del ginocchio, invece, non ci sono grandi differenze fra le due scelte.", "Questo non significa che aspettare sia sempre sbagliato: la decisione va sempre discussa con il proprio chirurgo caso per caso. Ma sapere che un'attesa prolungata puo aumentare il rischio per il menisco e un'informazione utile per la scelta."]}, "linkedin": {"chir": ["Operare il LCA entro tre mesi: meno lesioni meniscali associate", "Revisione sistematica di 11 studi, oltre 9500 pazienti: lesione del menisco mediale piu frequente con ricostruzione ritardata oltre 3 mesi (59,6% contro 49,5%); nessun vantaggio chiaro su PROM per nessuno dei due tempi.", "Studi tutti osservazionali: il timing non e randomizzato, e chi arriva tardi all'intervento puo differire per motivi che spiegano anche il danno meniscale (confondimento per indicazione).\n\nHeder Ternell, Nilsson, Cristiani et al., Journal of ISAKOS, settembre 2026."], "misto": ["Aspettare per operare il crociato ha un costo per il menisco", "Una revisione di 11 studi, con oltre 9500 pazienti in totale, mostra che chi ricostruisce il legamento crociato entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco interno rispetto a chi aspetta piu a lungo.", "Sui punteggi di funzione del ginocchio non emerge invece un vantaggio chiaro per l'una o l'altra scelta di tempistica: la decisione resta individuale, ma il dato sul menisco e un argomento in piu per non rimandare troppo.\n\nHeder Ternell, Nilsson, Cristiani et al., Journal of ISAKOS, settembre 2026."], "pazienti": ["Il legamento del ginocchio si puo aspettare a operarlo? Un dato sul menisco aiuta a decidere", "Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri aspettano facendo prima fisioterapia. Uno studio ha riunito i dati di oltre 9500 pazienti per vedere cosa cambia.", "Chi aspetta piu di tre mesi ha una probabilita maggiore di avere anche una lesione del menisco. Sulla funzione del ginocchio, invece, non emerge un vantaggio chiaro per nessuna delle due strade: la scelta va discussa caso per caso col chirurgo.\n\nHeder Ternell, Nilsson, Cristiani et al., Journal of ISAKOS, settembre 2026."]}, "instagram": {"chir": ["Operare il LCA entro tre mesi riduce le lesioni meniscali associate\nOperare il LCA entro tre mesi: meno lesioni meniscali associate", "Revisione sistematica di 11 studi, oltre 9500 pazienti: lesione del menisco mediale piu frequente con ricostruzione ritardata oltre 3 mesi (59,6% contro 49,5%); nessun vantaggio chiaro su PROM per nessuno dei due tempi.", "Studi tutti osservazionali: il timing non e randomizzato, e chi arriva tardi all'intervento puo differire per motivi che spiegano anche il danno meniscale (confondimento per indicazione)."], "misto": ["Operare il LCA entro tre mesi riduce le lesioni meniscali associate\nAspettare per operare il crociato ha un costo per il menisco", "Una revisione di 11 studi, con oltre 9500 pazienti in totale, mostra che chi ricostruisce il legamento crociato entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco interno rispetto a chi aspetta piu a lungo.", "Sui punteggi di funzione del ginocchio non emerge invece un vantaggio chiaro per l'una o l'altra scelta di tempistica: la decisione resta individuale, ma il dato sul menisco e un argomento in piu per non rimandare troppo."], "pazienti": ["Operare il LCA entro tre mesi riduce le lesioni meniscali associate\nIl legamento del ginocchio si puo aspettare a operarlo? Un dato sul menisco aiuta a decidere", "Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri aspettano facendo prima fisioterapia.\nUno studio ha riunito i dati di oltre 9500 pazienti per vedere cosa cambia.", "Chi aspetta piu di tre mesi ha una probabilita maggiore di avere anche una lesione del menisco.\nSulla funzione del ginocchio, invece, non emerge un vantaggio chiaro per nessuna delle due strade: la scelta va discussa caso per caso col chirurgo."]}, "reel": {"chir": ["[IL DATO] Operare il LCA entro tre mesi: meno lesioni meniscali associate", "[COSA SIGNIFICA] Revisione sistematica di 11 studi, oltre 9500 pazienti: lesione del menisco mediale piu frequente con ricostruzione ritardata oltre 3 mesi (59,6% contro 49,5%); nessun vantaggio chiaro su PROM per nessuno dei due tempi.", "[IL LIMITE] Studi tutti osservazionali: il timing non e randomizzato, e chi arriva tardi all'intervento puo differire per motivi che spiegano anche il danno meniscale (confondimento per indicazione)."], "misto": ["[COSA DICE LO STUDIO] Aspettare per operare il crociato ha un costo per il menisco", "[PERCHE CONTA] Una revisione di 11 studi, con oltre 9500 pazienti in totale, mostra che chi ricostruisce il legamento crociato entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco interno rispetto a chi aspetta piu a lungo.", "[IL LIMITE] Sui punteggi di funzione del ginocchio non emerge invece un vantaggio chiaro per l'una o l'altra scelta di tempistica: la decisione resta individuale, ma il dato sul menisco e un argomento in piu per non rimandare troppo."], "pazienti": ["[COSA DICE LO STUDIO] Il legamento del ginocchio si puo aspettare a operarlo? Un dato sul menisco aiuta a decidere", "[COSA CAMBIA PER TE] Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri aspettano facendo prima fisioterapia. Uno studio ha riunito i dati di oltre 9500 pazienti per vedere cosa cambia.", "[IL LIMITE] Chi aspetta piu di tre mesi ha una probabilita maggiore di avere anche una lesione del menisco. Sulla funzione del ginocchio, invece, non emerge un vantaggio chiaro per nessuna delle due strade: la scelta va discussa caso per caso col chirurgo."]}}, "4": {"video": {"chir": ["Il criterio piu usato per decidere quando un atleta puo tornare a giocare dopo la ricostruzione del legamento crociato anteriore e il confronto della forza fra le due gambe, il cosiddetto indice di simmetria o LSI. Uno studio su centoventisette atleti professionisti ha voluto verificare quanto questo indice predica davvero il rischio di un nuovo infortunio.", "Il risultato e sorprendente: l'indice di simmetria ha un valore predittivo molto limitato, significativo solo in un test su dieci e solo nelle atlete donne. Le performance assolute nei test di salto, invece, correlano fortemente — con coefficienti fino a 0,73 — con quanto l'atleta si sente psicologicamente pronto a tornare in campo, misurato con una scala validata chiamata ACL-RSI.", "Il campione degli atleti realmente reinfortunati e piccolo, trentadue casi confrontati con altrettanti controlli, quindi il segnale va confermato su numeri piu ampi. Ma il messaggio pratico e chiaro: affidarsi solo al confronto di forza fra le due gambe per decidere il rientro rischia di lasciare fuori una parte importante dell'informazione, quella psicologica."], "misto": ["Per decidere quando un atleta puo tornare a giocare dopo l'intervento al legamento crociato anteriore, il test piu usato confronta la forza delle due gambe: se sono abbastanza simili, si da il via libera. Uno studio su centoventisette atleti professionisti ha verificato se questo test funzioni davvero bene per prevedere chi si fara male di nuovo.", "Il risultato mostra che questo confronto di forza, da solo, predice poco il rischio di reinfortunio. Molto piu collegata al rischio e invece la prontezza psicologica dell'atleta, cioe quanto si sente sicuro e pronto mentalmente a tornare a livelli intensi di gioco, misurata con un questionario apposito.", "Lo studio ha seguito un numero limitato di atleti che si sono davvero reinfortunati, quindi il dato va confermato con ricerche piu ampie. Ma suggerisce che, nel percorso di rientro, la componente psicologica meriti la stessa attenzione data ai test fisici."], "pazienti": ["Dopo l'intervento per ricostruire il legamento crociato del ginocchio, molti chirurghi decidono se un atleta puo tornare a giocare confrontando la forza delle due gambe. Uno studio su centoventisette atleti professionisti ha verificato se questo modo di decidere funzioni bene per evitare un nuovo infortunio.", "E emerso che il solo confronto di forza tra le gambe non basta a prevedere chi si fara male di nuovo. Molto piu importante sembra essere quanto la persona si senta psicologicamente pronta e sicura di se stessa nel tornare all'attivita sportiva intensa.", "Lo studio riguarda atleti professionisti, e i casi di nuovo infortunio osservati sono pochi, quindi serve conferma su numeri piu grandi. Ma il messaggio e utile anche per chi pratica sport a livello amatoriale: sentirsi pronti mentalmente conta quanto essere forti fisicamente."]}, "linkedin": {"chir": ["LSI insufficiente: conta anche la prontezza psicologica per il rientro", "127 atleti professionisti, caso-controllo annidato su 32 reinfortuni: l'indice di simmetria di forza (LSI) discrimina poco il reinfortunio (1 solo test significativo, solo nelle donne, p=0,03); l'ACL-RSI correla fortemente con le performance di hop test (r 0,43-0,73).", "Campione caso-controllo ridotto (32 coppie): le correlazioni sono forti ma basate su pochi eventi di reinfortunio.\n\nRahimi Khoygani, Esmaeili, Sports Health, settembre 2026."], "misto": ["Tornare in campo dopo il crociato: la testa conta quanto le gambe", "Uno studio su 127 atleti professionisti mostra che il test piu usato per decidere il rientro allo sport — il confronto di forza fra le due gambe — non predice bene chi si reinfortunera. Una scala che misura quanto l'atleta si sente psicologicamente pronto, invece, si collega molto piu chiaramente alle sue prestazioni fisiche.", "Il campione degli atleti che si sono davvero reinfortunati e piccolo (32 casi): un segnale forte, ma da confermare su numeri piu ampi.\n\nRahimi Khoygani, Esmaeili, Sports Health, settembre 2026."], "pazienti": ["Dopo l'intervento al crociato, sentirsi pronti conta quanto essere forti", "Molti chirurghi decidono se un atleta puo tornare a giocare misurando la forza delle due gambe. Uno studio su 127 atleti professionisti mostra che questo test da solo non basta a prevedere chi si fara male di nuovo.", "Una valutazione di quanto l'atleta si senta psicologicamente pronto sembra un'informazione altrettanto importante. Lo studio riguarda atleti professionisti: nello sport amatoriale il messaggio di fondo — la mente conta quanto il corpo — resta comunque utile.\n\nRahimi Khoygani, Esmaeili, Sports Health, settembre 2026."]}, "instagram": {"chir": ["Nel rientro allo sport la prontezza psicologica conta quanto i test\nLSI insufficiente: conta anche la prontezza psicologica per il rientro", "127 atleti professionisti, caso-controllo annidato su 32 reinfortuni: l'indice di simmetria di forza (LSI) discrimina poco il reinfortunio (1 solo test significativo, solo nelle donne, p=0,03); l'ACL-RSI correla fortemente con le performance di hop test (r 0,43-0,73).", "Campione caso-controllo ridotto (32 coppie): le correlazioni sono forti ma basate su pochi eventi di reinfortunio."], "misto": ["Nel rientro allo sport la prontezza psicologica conta quanto i test\nTornare in campo dopo il crociato: la testa conta quanto le gambe", "Uno studio su 127 atleti professionisti mostra che il test piu usato per decidere il rientro allo sport — il confronto di forza fra le due gambe — non predice bene chi si reinfortunera.\nUna scala che misura quanto l'atleta si sente psicologicamente pronto, invece, si collega molto piu chiaramente alle sue prestazioni fisiche.", "Il campione degli atleti che si sono davvero reinfortunati e piccolo (32 casi): un segnale forte, ma da confermare su numeri piu ampi."], "pazienti": ["Nel rientro allo sport la prontezza psicologica conta quanto i test\nDopo l'intervento al crociato, sentirsi pronti conta quanto essere forti", "Molti chirurghi decidono se un atleta puo tornare a giocare misurando la forza delle due gambe.\nUno studio su 127 atleti professionisti mostra che questo test da solo non basta a prevedere chi si fara male di nuovo.", "Una valutazione di quanto l'atleta si senta psicologicamente pronto sembra un'informazione altrettanto importante.\nLo studio riguarda atleti professionisti: nello sport amatoriale il messaggio di fondo — la mente conta quanto il corpo — resta comunque utile."]}, "reel": {"chir": ["[IL DATO] LSI insufficiente: conta anche la prontezza psicologica per il rientro", "[COSA SIGNIFICA] 127 atleti professionisti, caso-controllo annidato su 32 reinfortuni: l'indice di simmetria di forza (LSI) discrimina poco il reinfortunio (1 solo test significativo, solo nelle donne, p=0,03); l'ACL-RSI correla fortemente con le performance di hop test (r 0,43-0,73).", "[IL LIMITE] Campione caso-controllo ridotto (32 coppie): le correlazioni sono forti ma basate su pochi eventi di reinfortunio."], "misto": ["[COSA DICE LO STUDIO] Tornare in campo dopo il crociato: la testa conta quanto le gambe", "[PERCHE CONTA] Uno studio su 127 atleti professionisti mostra che il test piu usato per decidere il rientro allo sport — il confronto di forza fra le due gambe — non predice bene chi si reinfortunera. Una scala che misura quanto l'atleta si sente psicologicamente pronto, invece, si collega molto piu chiaramente alle sue prestazioni fisiche.", "[IL LIMITE] Il campione degli atleti che si sono davvero reinfortunati e piccolo (32 casi): un segnale forte, ma da confermare su numeri piu ampi."], "pazienti": ["[COSA DICE LO STUDIO] Dopo l'intervento al crociato, sentirsi pronti conta quanto essere forti", "[COSA CAMBIA PER TE] Molti chirurghi decidono se un atleta puo tornare a giocare misurando la forza delle due gambe. Uno studio su 127 atleti professionisti mostra che questo test da solo non basta a prevedere chi si fara male di nuovo.", "[IL LIMITE] Una valutazione di quanto l'atleta si senta psicologicamente pronto sembra un'informazione altrettanto importante. Lo studio riguarda atleti professionisti: nello sport amatoriale il messaggio di fondo — la mente conta quanto il corpo — resta comunque utile."]}}, "5": {"video": {"chir": ["Dopo la ricostruzione del legamento crociato anteriore, il muscolo quadricipite spesso resta indebolito per mesi. Uno studio ha seguito cinquantanove pazienti per un anno intero, misurando sia il recupero della forza sia il modo di camminare, per capire se le due cose siano collegate nel tempo.", "Sono emerse due traiettorie distinte di recupero della forza: chi recupera meno forza mantiene, anche a dodici mesi dall'intervento, una minore flessione del ginocchio e un momento estensorio piu basso durante il cammino rispetto a chi recupera meglio — alterazioni gia collegate in altri studi al rischio di artrosi post-traumatica futura.", "Il dato interessante e che anche chi recupera bene la forza non normalizza del tutto il proprio modo di camminare rispetto a persone mai operate. Il campione e moderato, cinquantanove pazienti, ma il messaggio pratico e chiaro: la sola forza muscolare non basta a garantire un cammino del tutto normale, e la riabilitazione dovrebbe guardare anche a questo."], "misto": ["Dopo l'intervento al legamento crociato anteriore, il muscolo davanti alla coscia — il quadricipite — spesso resta piu debole per diversi mesi. Uno studio ha seguito cinquantanove pazienti per un anno intero, guardando sia quanta forza recuperavano sia come camminavano nel tempo.", "I pazienti che recuperano meno forza continuano a camminare in modo un po' diverso anche dopo un anno, con un ginocchio che si piega meno durante il passo — un pattern che altri studi collegano al rischio di artrosi negli anni successivi. Chi recupera piu forza cammina meglio, ma nemmeno in questo caso il cammino torna del tutto come prima dell'infortunio.", "Il messaggio pratico e che rinforzare il quadricipite dopo l'intervento resta fondamentale, ma potrebbe non bastare da solo: potrebbe servire un lavoro specifico anche sul modo di camminare, non solo sulla forza muscolare misurata in palestra."], "pazienti": ["Dopo l'intervento al legamento crociato del ginocchio, il muscolo davanti alla coscia spesso rimane piu debole per un po' di tempo. Uno studio ha seguito cinquantanove persone per un anno intero, per vedere se questa debolezza influisce sul modo di camminare.", "Chi recupera meno forza in quel muscolo continua a camminare in modo leggermente diverso anche dopo un anno dall'intervento. Chi invece recupera bene cammina meglio, anche se non esattamente come prima dell'infortunio.", "Questo conferma quanto sia importante seguire con costanza il percorso di riabilitazione e il rinforzo muscolare consigliato dal fisioterapista anche mesi dopo l'intervento, non solo nelle prime settimane."]}, "linkedin": {"chir": ["Recupero di forza del quadricipite e cammino: due traiettorie diverse a un anno", "59 pazienti, due profili di recupero della forza post-LCA: il gruppo con recupero minore mantiene flessione e momento estensorio del ginocchio piu bassi durante il cammino fino a 12 mesi; anche il gruppo con recupero maggiore non si normalizza del tutto verso i controlli sani.", "Campione moderato (59 pazienti, due sottogruppi piu piccoli); il legame con un esito clinico duro come l'artrosi non e ancora dimostrato in questo studio.\n\nLemus, Buttner, Arbeeva et al., Sports Health, settembre 2026."], "misto": ["Recuperare piu forza dopo il crociato cambia anche il modo di camminare", "In uno studio su 59 pazienti seguiti per un anno dopo la ricostruzione del crociato, chi recupera meno forza del muscolo quadricipite continua a camminare in modo diverso rispetto a chi ne recupera di piu — un pattern legato, in altri studi, al rischio di artrosi futura.", "Anche chi recupera bene la forza non torna a camminare esattamente come prima dell'infortunio: un argomento per non fermare la riabilitazione al solo recupero della forza muscolare.\n\nLemus, Buttner, Arbeeva et al., Sports Health, settembre 2026."], "pazienti": ["Dopo l'intervento al crociato, riguadagnare forza nella coscia aiuta anche a camminare meglio", "Uno studio ha seguito 59 persone per un anno dopo l'intervento al legamento crociato, misurando sia la forza del muscolo davanti alla coscia sia il modo di camminare.", "Chi recupera meno forza cammina in modo un po' diverso ancora a un anno dall'intervento. Anche chi recupera bene non torna esattamente come prima: la riabilitazione conta, e vale la pena seguirla con costanza anche dopo i primi mesi.\n\nLemus, Buttner, Arbeeva et al., Sports Health, settembre 2026."]}, "instagram": {"chir": ["Chi recupera meno forza del quadricipite cammina peggio anche a un anno\nRecupero di forza del quadricipite e cammino: due traiettorie diverse a un anno", "59 pazienti, due profili di recupero della forza post-LCA: il gruppo con recupero minore mantiene flessione e momento estensorio del ginocchio piu bassi durante il cammino fino a 12 mesi; anche il gruppo con recupero maggiore non si normalizza del tutto verso i controlli sani.", "Campione moderato (59 pazienti, due sottogruppi piu piccoli); il legame con un esito clinico duro come l'artrosi non e ancora dimostrato in questo studio."], "misto": ["Chi recupera meno forza del quadricipite cammina peggio anche a un anno\nRecuperare piu forza dopo il crociato cambia anche il modo di camminare", "In uno studio su 59 pazienti seguiti per un anno dopo la ricostruzione del crociato, chi recupera meno forza del muscolo quadricipite continua a camminare in modo diverso rispetto a chi ne recupera di piu — un pattern legato, in altri studi, al rischio di artrosi futura.", "Anche chi recupera bene la forza non torna a camminare esattamente come prima dell'infortunio: un argomento per non fermare la riabilitazione al solo recupero della forza muscolare."], "pazienti": ["Chi recupera meno forza del quadricipite cammina peggio anche a un anno\nDopo l'intervento al crociato, riguadagnare forza nella coscia aiuta anche a camminare meglio", "Uno studio ha seguito 59 persone per un anno dopo l'intervento al legamento crociato, misurando sia la forza del muscolo davanti alla coscia sia il modo di camminare.", "Chi recupera meno forza cammina in modo un po' diverso ancora a un anno dall'intervento.\nAnche chi recupera bene non torna esattamente come prima: la riabilitazione conta, e vale la pena seguirla con costanza anche dopo i primi mesi."]}, "reel": {"chir": ["[IL DATO] Recupero di forza del quadricipite e cammino: due traiettorie diverse a un anno", "[COSA SIGNIFICA] 59 pazienti, due profili di recupero della forza post-LCA: il gruppo con recupero minore mantiene flessione e momento estensorio del ginocchio piu bassi durante il cammino fino a 12 mesi; anche il gruppo con recupero maggiore non si normalizza del tutto verso i controlli sani.", "[IL LIMITE] Campione moderato (59 pazienti, due sottogruppi piu piccoli); il legame con un esito clinico duro come l'artrosi non e ancora dimostrato in questo studio."], "misto": ["[COSA DICE LO STUDIO] Recuperare piu forza dopo il crociato cambia anche il modo di camminare", "[PERCHE CONTA] In uno studio su 59 pazienti seguiti per un anno dopo la ricostruzione del crociato, chi recupera meno forza del muscolo quadricipite continua a camminare in modo diverso rispetto a chi ne recupera di piu — un pattern legato, in altri studi, al rischio di artrosi futura.", "[IL LIMITE] Anche chi recupera bene la forza non torna a camminare esattamente come prima dell'infortunio: un argomento per non fermare la riabilitazione al solo recupero della forza muscolare."], "pazienti": ["[COSA DICE LO STUDIO] Dopo l'intervento al crociato, riguadagnare forza nella coscia aiuta anche a camminare meglio", "[COSA CAMBIA PER TE] Uno studio ha seguito 59 persone per un anno dopo l'intervento al legamento crociato, misurando sia la forza del muscolo davanti alla coscia sia il modo di camminare.", "[IL LIMITE] Chi recupera meno forza cammina in modo un po' diverso ancora a un anno dall'intervento. Anche chi recupera bene non torna esattamente come prima: la riabilitazione conta, e vale la pena seguirla con costanza anche dopo i primi mesi."]}}, "6": {"video": {"chir": ["Per pianificare una correzione dell'asse della gamba, come un'osteotomia, i chirurghi guardano di solito a un unico angolo complessivo, l'HKA. Uno studio coreano ha seguito settecentosessantaquattro ginocchia per oltre dieci anni, scomponendo l'allineamento nei suoi due componenti separati — l'angolo del femore e quello della tibia — per vedere se contasse anche la loro combinazione specifica.", "Il risultato mostra che alcune combinazioni particolari di angolo femorale e tibiale aumentano il rischio di progressione dell'artrosi fino a sette volte rispetto alla combinazione neutra di riferimento, anche quando l'angolo complessivo dell'arto potrebbe apparire normale o solo lievemente alterato. L'associazione resta forte anche dopo aver corretto l'analisi per altri fattori.", "Lo studio e retrospettivo e alcuni dei sottogruppi analizzati sono piccoli, con intervalli di confidenza ampi. Ma il principio e utile per la pratica: quando si pianifica una correzione dell'asse della gamba, guardare solo all'angolo complessivo potrebbe non bastare a valutare davvero il rischio futuro di artrosi."], "misto": ["Quando un chirurgo deve decidere se e come correggere l'asse di una gamba storta, di solito guarda a un unico numero che riassume l'allineamento complessivo. Uno studio coreano ha seguito oltre settecento ginocchia per piu di dieci anni, scomponendo questo numero nei due angoli separati — quello del femore e quello della tibia — per vedere se la loro combinazione specifica facesse la differenza.", "E emerso che certe combinazioni di questi due angoli aumentano molto il rischio che l'artrosi peggiori nel tempo, anche quando l'angolo complessivo della gamba sembrerebbe normale. In pratica, due gambe che sembrano allineate allo stesso modo possono nascondere rischi diversi a seconda di come e distribuito quell'allineamento fra femore e tibia.", "Lo studio guarda al passato, non e un esperimento controllato, e alcuni gruppi analizzati sono piccoli. Ma suggerisce che, quando si pianifica un intervento di correzione, vale la pena guardare oltre il solo numero complessivo dell'allineamento della gamba."], "pazienti": ["Quando il ginocchio e storto per l'artrosi, a volte serve un intervento per raddrizzare l'asse della gamba. Uno studio ha seguito oltre settecento ginocchia per piu di dieci anni, guardando non solo se la gamba nel complesso e dritta o storta, ma come sono orientati separatamente l'osso della coscia e quello della gamba.", "E emerso che alcune combinazioni specifiche di questi due orientamenti aumentano molto il rischio che l'artrosi peggiori negli anni, anche quando la gamba nel suo insieme sembra ragionevolmente dritta.", "E un dato tecnico, ma utile: significa che il chirurgo, quando valuta un eventuale intervento di correzione, puo guardare a piu dettagli che al solo aspetto generale della gamba, per capire meglio il rischio futuro e pianificare la soluzione migliore."]}, "linkedin": {"chir": ["Il fenotipo funzionale del ginocchio predice l'artrosi meglio del solo HKA", "Coorte coreana, 764 ginocchia, oltre 10 anni: tre combinazioni di angolo femorale e tibiale (non il solo HKA) aumentano il rischio di progressione artrosica fino a 7 volte rispetto al fenotipo neutro (OR aggiustati 3,10-7,50).", "Sottogruppi disuguali, alcuni piccoli (20 ginocchia): intervalli di confidenza ampi nei gruppi minori; nessun dato su esiti clinici riferiti dal paziente.\n\nSong, Lee, Park, Knee Surg Sports Traumatol Arthrosc, settembre 2026."], "misto": ["Non basta guardare l'asse della gamba per prevedere l'artrosi del ginocchio", "Uno studio coreano ha seguito 764 ginocchia per oltre dieci anni, scomponendo l'allineamento della gamba nei suoi due componenti — femore e tibia — invece di guardare solo l'angolo complessivo.", "Alcune combinazioni specifiche di questi due angoli aumentano molto il rischio di artrosi, anche quando l'angolo complessivo sembrerebbe normale: un dato utile per chi pianifica interventi di correzione dell'asse della gamba.\n\nSong, Lee, Park, Knee Surg Sports Traumatol Arthrosc, settembre 2026."], "pazienti": ["Anche una gamba che sembra dritta puo nascondere un rischio di artrosi", "Uno studio ha seguito piu di 700 ginocchia per oltre dieci anni, guardando non solo se la gamba e dritta o storta nel complesso, ma come sono orientati separatamente femore e tibia.", "Certe combinazioni aumentano il rischio che l'artrosi peggiori nel tempo, anche quando l'asse complessivo della gamba sembra normale — un'informazione che il chirurgo puo usare per pianificare al meglio un eventuale intervento di correzione.\n\nSong, Lee, Park, Knee Surg Sports Traumatol Arthrosc, settembre 2026."]}, "instagram": {"chir": ["Non solo l'asse: il fenotipo funzionale del ginocchio predice l'artrosi a 10 anni\nIl fenotipo funzionale del ginocchio predice l'artrosi meglio del solo HKA", "Coorte coreana, 764 ginocchia, oltre 10 anni: tre combinazioni di angolo femorale e tibiale (non il solo HKA) aumentano il rischio di progressione artrosica fino a 7 volte rispetto al fenotipo neutro (OR aggiustati 3,10-7,50).", "Sottogruppi disuguali, alcuni piccoli (20 ginocchia): intervalli di confidenza ampi nei gruppi minori; nessun dato su esiti clinici riferiti dal paziente."], "misto": ["Non solo l'asse: il fenotipo funzionale del ginocchio predice l'artrosi a 10 anni\nNon basta guardare l'asse della gamba per prevedere l'artrosi del ginocchio", "Uno studio coreano ha seguito 764 ginocchia per oltre dieci anni, scomponendo l'allineamento della gamba nei suoi due componenti — femore e tibia — invece di guardare solo l'angolo complessivo.", "Alcune combinazioni specifiche di questi due angoli aumentano molto il rischio di artrosi, anche quando l'angolo complessivo sembrerebbe normale: un dato utile per chi pianifica interventi di correzione dell'asse della gamba."], "pazienti": ["Non solo l'asse: il fenotipo funzionale del ginocchio predice l'artrosi a 10 anni\nAnche una gamba che sembra dritta puo nascondere un rischio di artrosi", "Uno studio ha seguito piu di 700 ginocchia per oltre dieci anni, guardando non solo se la gamba e dritta o storta nel complesso, ma come sono orientati separatamente femore e tibia.", "Certe combinazioni aumentano il rischio che l'artrosi peggiori nel tempo, anche quando l'asse complessivo della gamba sembra normale — un'informazione che il chirurgo puo usare per pianificare al meglio un eventuale intervento di correzione."]}, "reel": {"chir": ["[IL DATO] Il fenotipo funzionale del ginocchio predice l'artrosi meglio del solo HKA", "[COSA SIGNIFICA] Coorte coreana, 764 ginocchia, oltre 10 anni: tre combinazioni di angolo femorale e tibiale (non il solo HKA) aumentano il rischio di progressione artrosica fino a 7 volte rispetto al fenotipo neutro (OR aggiustati 3,10-7,50).", "[IL LIMITE] Sottogruppi disuguali, alcuni piccoli (20 ginocchia): intervalli di confidenza ampi nei gruppi minori; nessun dato su esiti clinici riferiti dal paziente."], "misto": ["[COSA DICE LO STUDIO] Non basta guardare l'asse della gamba per prevedere l'artrosi del ginocchio", "[PERCHE CONTA] Uno studio coreano ha seguito 764 ginocchia per oltre dieci anni, scomponendo l'allineamento della gamba nei suoi due componenti — femore e tibia — invece di guardare solo l'angolo complessivo.", "[IL LIMITE] Alcune combinazioni specifiche di questi due angoli aumentano molto il rischio di artrosi, anche quando l'angolo complessivo sembrerebbe normale: un dato utile per chi pianifica interventi di correzione dell'asse della gamba."], "pazienti": ["[COSA DICE LO STUDIO] Anche una gamba che sembra dritta puo nascondere un rischio di artrosi", "[COSA CAMBIA PER TE] Uno studio ha seguito piu di 700 ginocchia per oltre dieci anni, guardando non solo se la gamba e dritta o storta nel complesso, ma come sono orientati separatamente femore e tibia.", "[IL LIMITE] Certe combinazioni aumentano il rischio che l'artrosi peggiori nel tempo, anche quando l'asse complessivo della gamba sembra normale — un'informazione che il chirurgo puo usare per pianificare al meglio un eventuale intervento di correzione."]}}, "7": {"video": {"chir": ["La protesi di ginocchio robot-assistita promette maggiore precisione rispetto alla tecnica manuale tradizionale. Uno studio su quattrocentotrenta pazienti ha confrontato le due tecniche misurando i punteggi funzionali riferiti dal paziente a tre, sei e dodici mesi, e ha guardato anche a un fattore raramente considerato: l'esperienza del chirurgo.", "A tre mesi, il gruppo operato con il robot mostra punteggi funzionali migliori di quasi cinque punti, ma questa differenza si riduce a sei mesi e scompare del tutto a dodici mesi. Il dato piu interessante emerge guardando all'esperienza: il vantaggio del robot a tre mesi e molto piu marcato per i chirurghi meno esperti, che con il robot raggiungono risultati vicini a quelli dei colleghi piu esperti.", "L'analisi sull'esperienza del chirurgo e stata condotta dopo aver visto i dati, quindi va confermata con studi disegnati apposta per questo confronto. Ma il messaggio pratico e chiaro: il vantaggio piu solido del robot non e nel risultato finale, dove converge con la tecnica manuale, ma nella capacita di appianare le differenze fra chirurghi con esperienza diversa."], "misto": ["La protesi di ginocchio con l'aiuto del robot promette di essere piu precisa della tecnica manuale classica. Uno studio su quattrocentotrenta pazienti ha confrontato le due tecniche nel tempo, guardando anche a un aspetto interessante: se l'esperienza del chirurgo che opera faccia la differenza.", "Nei primi tre mesi dopo l'intervento, chi e stato operato con il robot ha punteggi di recupero leggermente migliori, ma questo vantaggio si riduce col tempo e sparisce del tutto a un anno di distanza. Il dato piu curioso: il beneficio del robot nei primi mesi e maggiore proprio quando a operare e un chirurgo con meno esperienza, che con il robot ottiene risultati vicini a quelli di un collega piu esperto.", "Questa parte dello studio sull'esperienza del chirurgo non era stata pianificata all'inizio, quindi va confermata con altre ricerche. Ma suggerisce che il robot possa aiutare soprattutto a livellare i risultati fra chirurghi diversi, piu che a migliorare il risultato finale in assoluto."], "pazienti": ["Nella protesi di ginocchio fatta con l'aiuto del robot, la tecnologia dovrebbe garantire maggiore precisione rispetto alla tecnica manuale classica. Uno studio su oltre quattrocento pazienti ha confrontato le due tecniche, guardando anche se l'esperienza del chirurgo che opera fa la differenza.", "Nei primi mesi dopo l'intervento, chi e stato operato con il robot recupera un po' piu velocemente, ma questo vantaggio scompare dopo un anno, quando i risultati con le due tecniche si equivalgono. Interessante notare che il vantaggio iniziale del robot e maggiore quando il chirurgo ha meno esperienza.", "Questo suggerisce che la tecnologia robotica possa aiutare soprattutto a rendere piu uniformi i risultati fra chirurghi diversi nei primi mesi, anche se sul risultato finale a lungo termine conta soprattutto la cura complessiva dell'intervento, non solo lo strumento usato."]}, "linkedin": {"chir": ["Protesi robotica: il vantaggio precoce e piu marcato per i chirurghi junior", "430 protesi (221 robot-assistite, 209 manuali): KOOS JR piu alto col robot a 3 mesi (+4,71 punti; IC 95% 2,35-7,08) ma non a 12 mesi (+0,89; p=0,461); beneficio maggiore nei chirurghi junior (+6,48 punti), che raggiungono risultati comparabili ai senior.", "Analisi sull'esperienza del chirurgo esplorativa e post hoc, non pre-pianificata; sistema robotico non specificato nell'abstract.\n\nZhang, Mao, Wu et al., Journal of Robotic Surgery, settembre 2026."], "misto": ["Con il robot, un chirurgo alle prime armi ottiene risultati simili a uno esperto", "Uno studio su 430 protesi di ginocchio confronta la tecnica robot-assistita con quella manuale, guardando anche all'esperienza del chirurgo. Il vantaggio del robot nei primi mesi e piu marcato proprio per i chirurghi meno esperti.", "A un anno di distanza, i risultati fra tecnica robotica e manuale si equivalgono: il beneficio del robot, quando c'e, si vede soprattutto nel recupero piu rapido nei primi mesi.\n\nZhang, Mao, Wu et al., Journal of Robotic Surgery, settembre 2026."], "pazienti": ["La protesi robotica puo aiutare soprattutto quando il chirurgo e alle prime esperienze", "In uno studio su 430 protesi di ginocchio, chi e stato operato con l'assistenza del robot ha recuperato un po' piu velocemente nei primi tre mesi, soprattutto quando l'intervento e stato eseguito da un chirurgo con meno anni di esperienza.", "A un anno di distanza il risultato finale e simile con o senza robot: la tecnologia sembra aiutare di piu a livellare il punto di partenza che a cambiare il traguardo finale.\n\nZhang, Mao, Wu et al., Journal of Robotic Surgery, settembre 2026."]}, "instagram": {"chir": ["La protesi robotica aiuta soprattutto i chirurghi meno esperti\nProtesi robotica: il vantaggio precoce e piu marcato per i chirurghi junior", "430 protesi (221 robot-assistite, 209 manuali): KOOS JR piu alto col robot a 3 mesi (+4,71 punti; IC 95% 2,35-7,08) ma non a 12 mesi (+0,89; p=0,461); beneficio maggiore nei chirurghi junior (+6,48 punti), che raggiungono risultati comparabili ai senior.", "Analisi sull'esperienza del chirurgo esplorativa e post hoc, non pre-pianificata; sistema robotico non specificato nell'abstract."], "misto": ["La protesi robotica aiuta soprattutto i chirurghi meno esperti\nCon il robot, un chirurgo alle prime armi ottiene risultati simili a uno esperto", "Uno studio su 430 protesi di ginocchio confronta la tecnica robot-assistita con quella manuale, guardando anche all'esperienza del chirurgo.\nIl vantaggio del robot nei primi mesi e piu marcato proprio per i chirurghi meno esperti.", "A un anno di distanza, i risultati fra tecnica robotica e manuale si equivalgono: il beneficio del robot, quando c'e, si vede soprattutto nel recupero piu rapido nei primi mesi."], "pazienti": ["La protesi robotica aiuta soprattutto i chirurghi meno esperti\nLa protesi robotica puo aiutare soprattutto quando il chirurgo e alle prime esperienze", "In uno studio su 430 protesi di ginocchio, chi e stato operato con l'assistenza del robot ha recuperato un po' piu velocemente nei primi tre mesi, soprattutto quando l'intervento e stato eseguito da un chirurgo con meno anni di esperienza.", "A un anno di distanza il risultato finale e simile con o senza robot: la tecnologia sembra aiutare di piu a livellare il punto di partenza che a cambiare il traguardo finale."]}, "reel": {"chir": ["[IL DATO] Protesi robotica: il vantaggio precoce e piu marcato per i chirurghi junior", "[COSA SIGNIFICA] 430 protesi (221 robot-assistite, 209 manuali): KOOS JR piu alto col robot a 3 mesi (+4,71 punti; IC 95% 2,35-7,08) ma non a 12 mesi (+0,89; p=0,461); beneficio maggiore nei chirurghi junior (+6,48 punti), che raggiungono risultati comparabili ai senior.", "[IL LIMITE] Analisi sull'esperienza del chirurgo esplorativa e post hoc, non pre-pianificata; sistema robotico non specificato nell'abstract."], "misto": ["[COSA DICE LO STUDIO] Con il robot, un chirurgo alle prime armi ottiene risultati simili a uno esperto", "[PERCHE CONTA] Uno studio su 430 protesi di ginocchio confronta la tecnica robot-assistita con quella manuale, guardando anche all'esperienza del chirurgo. Il vantaggio del robot nei primi mesi e piu marcato proprio per i chirurghi meno esperti.", "[IL LIMITE] A un anno di distanza, i risultati fra tecnica robotica e manuale si equivalgono: il beneficio del robot, quando c'e, si vede soprattutto nel recupero piu rapido nei primi mesi."], "pazienti": ["[COSA DICE LO STUDIO] La protesi robotica puo aiutare soprattutto quando il chirurgo e alle prime esperienze", "[COSA CAMBIA PER TE] In uno studio su 430 protesi di ginocchio, chi e stato operato con l'assistenza del robot ha recuperato un po' piu velocemente nei primi tre mesi, soprattutto quando l'intervento e stato eseguito da un chirurgo con meno anni di esperienza.", "[IL LIMITE] A un anno di distanza il risultato finale e simile con o senza robot: la tecnologia sembra aiutare di piu a livellare il punto di partenza che a cambiare il traguardo finale."]}}, "8": {"video": {"chir": ["Semaglutide e tirzepatide sono due farmaci per il diabete di tipo 2, sempre piu spesso prescritti anche a pazienti che devono affrontare una protesi totale di ginocchio. Uno studio su un grande database sanitario americano ha confrontato la sicurezza dei due farmaci nel periodo intorno all'intervento, abbinando ottocentotrenta pazienti per caratteristiche simili.", "Non emerge alcuna differenza significativa fra i due farmaci sulle complicanze mediche a novanta giorni ne su quelle chirurgiche a centottanta giorni. Anche eventi specifici come l'infezione del sito chirurgico, l'infezione periprotesica o le visite in pronto soccorso risultano statisticamente simili fra i due gruppi.", "Il limite principale e che alcuni di questi eventi sono rari, quindi gli intervalli di confidenza restano ampi e non escludono del tutto una differenza clinicamente rilevante in un senso o nell'altro — per esempio sull'infezione del sito chirurgico l'intervallo arriva quasi a quadruplicare il rischio. Il messaggio pratico e che, con i dati attuali, non c'e un motivo chiaro per preferire un farmaco all'altro in vista dell'intervento."], "misto": ["Semaglutide e tirzepatide sono due farmaci per il diabete sempre piu diffusi, anche fra chi si prepara a un intervento di protesi di ginocchio. Uno studio su un ampio database sanitario ha confrontato la sicurezza dei due farmaci nel periodo intorno all'intervento, su oltre ottocento pazienti diabetici.", "Il risultato e rassicurante: non emergono differenze importanti fra i due farmaci sulle complicanze mediche o chirurgiche nei mesi successivi all'operazione, ne su eventi specifici come le infezioni o le visite in pronto soccorso.", "Va detto che alcuni di questi eventi sono comunque rari, quindi i numeri restano un po' imprecisi e non permettono di escludere del tutto piccole differenze fra i due farmaci. Ma il messaggio di fondo e che nessuno dei due sembra da preferire per motivi di sicurezza chirurgica."], "pazienti": ["Se prendi un farmaco per il diabete come semaglutide o tirzepatide e ti stai preparando a una protesi di ginocchio, potresti chiederti se uno dei due sia piu sicuro dell'altro intorno all'intervento. Uno studio su oltre ottocento pazienti ha confrontato i due farmaci proprio su questo.", "La buona notizia e che non sono emerse differenze importanti di sicurezza fra i due farmaci nel periodo dell'intervento, ne su complicazioni mediche ne su complicazioni chirurgiche come le infezioni.", "Questo non significa che i due farmaci siano identici in tutto, ma per quanto riguarda la sicurezza dell'intervento di protesi non emerge un motivo per preferirne uno. La scelta del farmaco resta comunque una decisione da prendere insieme al proprio medico diabetologo."]}, "linkedin": {"chir": ["Semaglutide o tirzepatide prima della protesi: nessun segnale di differenza", "830 pazienti diabetici, propensity-matched: nessuna differenza a 90/180 giorni su complicanze mediche (OR 1,122) o chirurgiche (OR 1,632); intervalli ampi sui singoli eventi (infezione del sito chirurgico OR 1,726; IC 95% 0,782-3,810).", "Database amministrativo, diagnosi per codice; eventi rari con intervalli di confidenza larghi che non escludono differenze clinicamente rilevanti fra i due farmaci.\n\nWu, Choudhury, Wu et al., The Knee, settembre 2026."], "misto": ["Due farmaci per il diabete a confronto prima della protesi di ginocchio", "Semaglutide e tirzepatide sono due farmaci sempre piu usati nei pazienti diabetici, anche prima di un intervento di protesi. Uno studio su oltre 800 pazienti abbinati per caratteristiche simili non trova differenze rilevanti fra i due farmaci sulla sicurezza dell'intervento.", "Alcuni eventi rari, come l'infezione della ferita chirurgica, restano stimati con margini di incertezza ampi: il messaggio pratico e che nessuno dei due farmaci sembra da preferire per motivi di sicurezza chirurgica, ma serve cautela sui numeri piu piccoli.\n\nWu, Choudhury, Wu et al., The Knee, settembre 2026."], "pazienti": ["Se prendi un farmaco per il diabete prima della protesi di ginocchio, quale scegliere?", "Due farmaci moderni per il diabete, sempre piu diffusi, sono stati confrontati in oltre 800 pazienti che si sono sottoposti a una protesi di ginocchio.", "Non sono emerse differenze importanti di sicurezza fra i due farmaci nel periodo intorno all'intervento. E un'informazione utile da condividere con il proprio diabetologo e chirurgo, non un motivo per cambiare terapia da soli.\n\nWu, Choudhury, Wu et al., The Knee, settembre 2026."]}, "instagram": {"chir": ["Semaglutide o tirzepatide prima della protesi: stessa sicurezza a breve termine\nSemaglutide o tirzepatide prima della protesi: nessun segnale di differenza", "830 pazienti diabetici, propensity-matched: nessuna differenza a 90/180 giorni su complicanze mediche (OR 1,122) o chirurgiche (OR 1,632); intervalli ampi sui singoli eventi (infezione del sito chirurgico OR 1,726; IC 95% 0,782-3,810).", "Database amministrativo, diagnosi per codice; eventi rari con intervalli di confidenza larghi che non escludono differenze clinicamente rilevanti fra i due farmaci."], "misto": ["Semaglutide o tirzepatide prima della protesi: stessa sicurezza a breve termine\nDue farmaci per il diabete a confronto prima della protesi di ginocchio", "Semaglutide e tirzepatide sono due farmaci sempre piu usati nei pazienti diabetici, anche prima di un intervento di protesi.\nUno studio su oltre 800 pazienti abbinati per caratteristiche simili non trova differenze rilevanti fra i due farmaci sulla sicurezza dell'intervento.", "Alcuni eventi rari, come l'infezione della ferita chirurgica, restano stimati con margini di incertezza ampi: il messaggio pratico e che nessuno dei due farmaci sembra da preferire per motivi di sicurezza chirurgica, ma serve cautela sui numeri piu piccoli."], "pazienti": ["Semaglutide o tirzepatide prima della protesi: stessa sicurezza a breve termine\nSe prendi un farmaco per il diabete prima della protesi di ginocchio, quale scegliere?", "Due farmaci moderni per il diabete, sempre piu diffusi, sono stati confrontati in oltre 800 pazienti che si sono sottoposti a una protesi di ginocchio.", "Non sono emerse differenze importanti di sicurezza fra i due farmaci nel periodo intorno all'intervento.\nE un'informazione utile da condividere con il proprio diabetologo e chirurgo, non un motivo per cambiare terapia da soli."]}, "reel": {"chir": ["[IL DATO] Semaglutide o tirzepatide prima della protesi: nessun segnale di differenza", "[COSA SIGNIFICA] 830 pazienti diabetici, propensity-matched: nessuna differenza a 90/180 giorni su complicanze mediche (OR 1,122) o chirurgiche (OR 1,632); intervalli ampi sui singoli eventi (infezione del sito chirurgico OR 1,726; IC 95% 0,782-3,810).", "[IL LIMITE] Database amministrativo, diagnosi per codice; eventi rari con intervalli di confidenza larghi che non escludono differenze clinicamente rilevanti fra i due farmaci."], "misto": ["[COSA DICE LO STUDIO] Due farmaci per il diabete a confronto prima della protesi di ginocchio", "[PERCHE CONTA] Semaglutide e tirzepatide sono due farmaci sempre piu usati nei pazienti diabetici, anche prima di un intervento di protesi. Uno studio su oltre 800 pazienti abbinati per caratteristiche simili non trova differenze rilevanti fra i due farmaci sulla sicurezza dell'intervento.", "[IL LIMITE] Alcuni eventi rari, come l'infezione della ferita chirurgica, restano stimati con margini di incertezza ampi: il messaggio pratico e che nessuno dei due farmaci sembra da preferire per motivi di sicurezza chirurgica, ma serve cautela sui numeri piu piccoli."], "pazienti": ["[COSA DICE LO STUDIO] Se prendi un farmaco per il diabete prima della protesi di ginocchio, quale scegliere?", "[COSA CAMBIA PER TE] Due farmaci moderni per il diabete, sempre piu diffusi, sono stati confrontati in oltre 800 pazienti che si sono sottoposti a una protesi di ginocchio.", "[IL LIMITE] Non sono emerse differenze importanti di sicurezza fra i due farmaci nel periodo intorno all'intervento. E un'informazione utile da condividere con il proprio diabetologo e chirurgo, non un motivo per cambiare terapia da soli."]}}, "9": {"video": {"chir": ["Quando si ripara il menisco per via artroscopica con la tecnica all-inside, si usano dispositivi diversi per fissare la sutura: alcuni a tutto-sutura, altri con un'ancora rigida che puo lasciare o meno un nodo a contatto con la superficie del menisco. Un editoriale commenta un'analisi delle segnalazioni di eventi avversi raccolte dalla Food and Drug Administration statunitense su questi dispositivi.", "Il dato principale e che i dispositivi con ancora rigida e senza nodo esposto sulla superficie del menisco risultano associati a meno segnalazioni di problemi rispetto sia ai dispositivi a tutto-sutura sia alle ancore rigide con nodo esposto. L'autore segnala anche che alcuni produttori riportano gli eventi avversi con molta piu lentezza di altri.", "Il limite e importante: e un editoriale di commento, non uno studio con analisi statistica propria, e i nomi dei dispositivi non sono riportati, quindi non si puo sapere quale sistema specifico sia coinvolto. Resta comunque un promemoria utile: il tipo di costrutto del dispositivo di sutura meniscale puo incidere sul profilo di sicurezza, non solo la tecnica chirurgica in se."], "misto": ["Quando si ripara il menisco durante un'artroscopia, si possono usare diversi tipi di dispositivi per fissare il punto di sutura: alcuni consistono in un filo che si annoda da solo, altri in una piccola ancora rigida che puo lasciare o no un nodo a contatto con il menisco. Un commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "Dall'analisi emerge che i dispositivi con ancora rigida senza nodo a contatto con il menisco sembrano avere meno segnalazioni di problemi rispetto agli altri due tipi. Viene anche segnalato che non tutte le aziende produttrici segnalano i problemi con la stessa rapidita.", "Il commento non permette di indicare quale marca specifica sia coinvolta, e non e uno studio con la propria analisi statistica indipendente. Ma e un promemoria utile che i dettagli tecnici del dispositivo usato per riparare il menisco possono fare la differenza, non solo la bravura del chirurgo."], "pazienti": ["Quando si ripara il menisco del ginocchio con un piccolo intervento in artroscopia, il chirurgo usa dei dispositivi speciali per fissare il punto di sutura. Ne esistono di tipi diversi, e un commento scientifico ha riassunto i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "E emerso che alcuni tipi di dispositivo sembrano dare meno problemi di altri, anche se il commento non permette di dire quale marca specifica sia piu sicura.", "Non e un motivo di preoccupazione per chi deve sottoporsi all'intervento: e piu un promemoria per gli specialisti che i dettagli tecnici contano. Il tuo chirurgo sceglie il dispositivo in base alla sua esperienza e alle caratteristiche della tua lesione."]}, "linkedin": {"chir": ["Le protesi di sutura meniscale non sono tutte uguali per gli eventi avversi", "Editoriale su un'analisi del database FDA MAUDE: le ancore rigide senza nodo esposto sulla superficie del menisco risultano associate a meno segnalazioni di eventi avversi rispetto ai dispositivi a tutto-sutura o con nodo esposto.", "Editoriale di livello V, senza analisi statistica propria ne correzione per il volume di impianti per categoria; nomi dei dispositivi non riportati.\n\nBarber, Arthroscopy, settembre 2026."], "misto": ["Anche il tipo di ancoretta usata per riparare il menisco puo fare la differenza", "Un commento editoriale riassume i dati di un database di sicurezza statunitense sui dispositivi usati per riparare il menisco per via artroscopica, distinguendo tre tipi di costrutto.", "I dispositivi con un'ancora rigida che non lascia un nodo a contatto con il menisco risultano associati a meno segnalazioni di problemi. Il dato non identifica marche specifiche e non tiene conto di quanti dispositivi di ciascun tipo siano stati impiantati in totale.\n\nBarber, Arthroscopy, settembre 2026."], "pazienti": ["Anche il tipo di punto usato per riparare il menisco puo contare", "Quando si ripara il menisco in artroscopia, si usano diversi tipi di dispositivi per fissare la sutura. Un commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "Alcuni tipi di fissaggio sembrano associarsi a meno problemi segnalati di altri, anche se il dato non permette di indicare una marca precisa. E un promemoria che i dettagli tecnici dell'intervento contano, piu che un motivo di allarme.\n\nBarber, Arthroscopy, settembre 2026."]}, "instagram": {"chir": ["Non tutte le protesi di sutura meniscale danno gli stessi problemi\nLe protesi di sutura meniscale non sono tutte uguali per gli eventi avversi", "Editoriale su un'analisi del database FDA MAUDE: le ancore rigide senza nodo esposto sulla superficie del menisco risultano associate a meno segnalazioni di eventi avversi rispetto ai dispositivi a tutto-sutura o con nodo esposto.", "Editoriale di livello V, senza analisi statistica propria ne correzione per il volume di impianti per categoria; nomi dei dispositivi non riportati."], "misto": ["Non tutte le protesi di sutura meniscale danno gli stessi problemi\nAnche il tipo di ancoretta usata per riparare il menisco puo fare la differenza", "Un commento editoriale riassume i dati di un database di sicurezza statunitense sui dispositivi usati per riparare il menisco per via artroscopica, distinguendo tre tipi di costrutto.", "I dispositivi con un'ancora rigida che non lascia un nodo a contatto con il menisco risultano associati a meno segnalazioni di problemi.\nIl dato non identifica marche specifiche e non tiene conto di quanti dispositivi di ciascun tipo siano stati impiantati in totale."], "pazienti": ["Non tutte le protesi di sutura meniscale danno gli stessi problemi\nAnche il tipo di punto usato per riparare il menisco puo contare", "Quando si ripara il menisco in artroscopia, si usano diversi tipi di dispositivi per fissare la sutura.\nUn commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "Alcuni tipi di fissaggio sembrano associarsi a meno problemi segnalati di altri, anche se il dato non permette di indicare una marca precisa.\nE un promemoria che i dettagli tecnici dell'intervento contano, piu che un motivo di allarme."]}, "reel": {"chir": ["[IL DATO] Le protesi di sutura meniscale non sono tutte uguali per gli eventi avversi", "[COSA SIGNIFICA] Editoriale su un'analisi del database FDA MAUDE: le ancore rigide senza nodo esposto sulla superficie del menisco risultano associate a meno segnalazioni di eventi avversi rispetto ai dispositivi a tutto-sutura o con nodo esposto.", "[IL LIMITE] Editoriale di livello V, senza analisi statistica propria ne correzione per il volume di impianti per categoria; nomi dei dispositivi non riportati."], "misto": ["[COSA DICE LO STUDIO] Anche il tipo di ancoretta usata per riparare il menisco puo fare la differenza", "[PERCHE CONTA] Un commento editoriale riassume i dati di un database di sicurezza statunitense sui dispositivi usati per riparare il menisco per via artroscopica, distinguendo tre tipi di costrutto.", "[IL LIMITE] I dispositivi con un'ancora rigida che non lascia un nodo a contatto con il menisco risultano associati a meno segnalazioni di problemi. Il dato non identifica marche specifiche e non tiene conto di quanti dispositivi di ciascun tipo siano stati impiantati in totale."], "pazienti": ["[COSA DICE LO STUDIO] Anche il tipo di punto usato per riparare il menisco puo contare", "[COSA CAMBIA PER TE] Quando si ripara il menisco in artroscopia, si usano diversi tipi di dispositivi per fissare la sutura. Un commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "[IL LIMITE] Alcuni tipi di fissaggio sembrano associarsi a meno problemi segnalati di altri, anche se il dato non permette di indicare una marca precisa. E un promemoria che i dettagli tecnici dell'intervento contano, piu che un motivo di allarme."]}}};
var TAGS={"1": {"linkedin": "#ACLReconstruction #SportsMedicine #OrthoResearch", "instagram": "#LCA #Ginocchio #ChirurgiaOrtopedica #Ortopedia #MedicinaSportiva #TendineQuadricipite #Hamstring #Ricerca #SaluteDelGinocchio", "kw": "innesto tendine quadricipite LCA, ricostruzione crociato anteriore innesto"}, "2": {"linkedin": "#ACLReconstruction #KneeSurgery #JointLaxity", "instagram": "#LCA #Ginocchio #Ortopedia #LassitaArticolare #ChirurgiaArtroscopica #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "lassita articolare ginocchio, rischio dopo ricostruzione crociato"}, "3": {"linkedin": "#ACLReconstruction #SportsMedicine #MeniscalTear", "instagram": "#LCA #Menisco #Ginocchio #Ortopedia #ChirurgiaOrtopedica #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "tempistica intervento crociato, quando operare LCA"}, "4": {"linkedin": "#ReturnToSport #ACLReconstruction #SportsPsychology", "instagram": "#LCA #RientroAlloSport #Ginocchio #Ortopedia #MedicinaSportiva #Psicologia #Ricerca #SaluteDelGinocchio", "kw": "test rientro sport crociato, psicologia rientro sport"}, "5": {"linkedin": "#ACLRehabilitation #GaitAnalysis #SportsMedicine", "instagram": "#LCA #Riabilitazione #Ginocchio #Ortopedia #Biomeccanica #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "forza quadricipite dopo crociato, riabilitazione LCA"}, "6": {"linkedin": "#KneeOsteotomy #KneeAlignment #OrthoResearch", "instagram": "#Osteotomia #Ginocchio #Ortopedia #ArtrosiGinocchio #Allineamento #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "allineamento ginocchio artrosi, osteotomia correzione asse"}, "7": {"linkedin": "#RoboticTKA #KneeArthroplasty #SurgicalOutcomes", "instagram": "#ProtesiGinocchio #Robotica #Ortopedia #ChirurgiaOrtopedica #ArtrosiGinocchio #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "protesi ginocchio robot, protesi ginocchio esperienza chirurgo"}, "8": {"linkedin": "#TKA #Diabetes #GLP1", "instagram": "#ProtesiGinocchio #Diabete #Ortopedia #ChirurgiaOrtopedica #Farmacologia #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "diabete protesi ginocchio, semaglutide tirzepatide chirurgia"}, "9": {"linkedin": "#MeniscalRepair #DeviceSafety #Arthroscopy", "instagram": "#Menisco #Ginocchio #Ortopedia #ChirurgiaArtroscopica #Dispositivi #MedicinaSportiva #Ricerca #SaluteDelGinocchio", "kw": "sutura menisco dispositivi sicurezza, riparazione menisco tecnica"}};
var NLB={"1": {"prof": ["Rianalisi di fragilita: la non-differenza fra hamstring e quadricipite regge", "Otto RCT, 562 pazienti: l'indice di fragilita continua inversa (media 17,4) mostra che gli esiti continui non significativi fra i due innesti nel LCA sono statisticamente robusti, non un artefatto della perdita al follow-up.", "Nessuno degli 8 RCT include il rinforzo laterale (LET): la robustezza riguarda l'innesto isolato, non la combinazione che si esegue di routine."], "mix": ["Tendine del ginocchio o tendine del quadricipite: la scienza dice davvero che sono uguali?", "Una nuova analisi statistica ha riesaminato otto studi randomizzati che confrontano due tipi di innesto per ricostruire il legamento crociato anteriore, e ha verificato se la conclusione «risultati simili» fosse solida o fragile.", "Il risultato conferma che la conclusione regge: i due innesti danno esiti a breve termine davvero comparabili, non un'apparenza statistica dovuta a pazienti persi durante lo studio."], "paz": ["Due tendini diversi per ricostruire il legamento del ginocchio, con risultati simili: uno studio lo conferma", "Per ricostruire il legamento crociato anteriore si possono usare tendini diversi. Una nuova analisi ha riesaminato otto studi scientifici che confrontano due di queste scelte, per capire se i risultati simili osservati fossero davvero affidabili.", "La conferma c'e: a breve termine i risultati restano confrontabili fra le due tecniche, un'informazione utile per il colloquio prima dell'intervento sulla scelta dell'innesto."], "kw": "innesto LCA, tendine quadricipite ricostruzione"}, "2": {"prof": ["Nella lassita articolare generalizzata, piu lassita residua dopo il LCA", "Meta-analisi di 13 studi, 3905 pazienti: IKDC e Lysholm significativamente piu bassi, Lachman e pivot shift piu spesso positivi in chi ha lassita generalizzata, senza differenza certa nel tasso di fallimento (OR 3,15; p=0,07, IC non riportato).", "L'assenza di significativita sul fallimento non e una dimostrazione di equivalenza: con un OR di 3,15 senza intervallo di confidenza, il dato resta impreciso."], "mix": ["Ginocchia piu «elastiche»: cosa cambia dopo la ricostruzione del legamento crociato", "Uno studio ha riunito i dati di quasi 4000 pazienti per capire se avere articolazioni naturalmente piu lasse in tutto il corpo influisca sui risultati dopo la ricostruzione del crociato anteriore.", "I punteggi funzionali risultano un po' piu bassi e i segni clinici di lassita piu frequenti in questi pazienti, mentre non e chiaro se il rischio di dover rioperare sia davvero piu alto: il numero disponibile non basta a dirlo con certezza."], "paz": ["Se le tue articolazioni sono naturalmente piu «elastiche», il crociato va seguito con attenzione in piu", "Alcune persone hanno articolazioni naturalmente piu mobili in tutto il corpo. Uno studio su quasi 4000 pazienti ha verificato se questo influisce sui risultati dopo l'intervento per il legamento crociato del ginocchio.", "Chi ha questa caratteristica tende ad avere un ginocchio un po' piu lasso anche dopo l'intervento, con punteggi di funzione leggermente inferiori. Non e chiaro se il rischio di un secondo intervento sia davvero maggiore: serve prudenza nel trarre conclusioni definitive."], "kw": "lassita articolare crociato, ricostruzione LCA rischio"}, "3": {"prof": ["Operare il LCA entro tre mesi: meno lesioni meniscali associate", "Revisione sistematica di 11 studi, oltre 9500 pazienti: lesione del menisco mediale piu frequente con ricostruzione ritardata oltre 3 mesi (59,6% contro 49,5%); nessun vantaggio chiaro su PROM per nessuno dei due tempi.", "Studi tutti osservazionali: il timing non e randomizzato, e chi arriva tardi all'intervento puo differire per motivi che spiegano anche il danno meniscale (confondimento per indicazione)."], "mix": ["Aspettare per operare il crociato ha un costo per il menisco", "Una revisione di 11 studi, con oltre 9500 pazienti in totale, mostra che chi ricostruisce il legamento crociato entro tre mesi dall'infortunio ha meno probabilita di avere anche una lesione del menisco interno rispetto a chi aspetta piu a lungo.", "Sui punteggi di funzione del ginocchio non emerge invece un vantaggio chiaro per l'una o l'altra scelta di tempistica: la decisione resta individuale, ma il dato sul menisco e un argomento in piu per non rimandare troppo."], "paz": ["Il legamento del ginocchio si puo aspettare a operarlo? Un dato sul menisco aiuta a decidere", "Dopo la rottura del legamento crociato anteriore, alcuni pazienti operano subito, altri aspettano facendo prima fisioterapia. Uno studio ha riunito i dati di oltre 9500 pazienti per vedere cosa cambia.", "Chi aspetta piu di tre mesi ha una probabilita maggiore di avere anche una lesione del menisco. Sulla funzione del ginocchio, invece, non emerge un vantaggio chiaro per nessuna delle due strade: la scelta va discussa caso per caso col chirurgo."], "kw": "tempistica intervento crociato, lesione menisco ritardo"}, "4": {"prof": ["LSI insufficiente: conta anche la prontezza psicologica per il rientro", "127 atleti professionisti, caso-controllo annidato su 32 reinfortuni: l'indice di simmetria di forza (LSI) discrimina poco il reinfortunio (1 solo test significativo, solo nelle donne, p=0,03); l'ACL-RSI correla fortemente con le performance di hop test (r 0,43-0,73).", "Campione caso-controllo ridotto (32 coppie): le correlazioni sono forti ma basate su pochi eventi di reinfortunio."], "mix": ["Tornare in campo dopo il crociato: la testa conta quanto le gambe", "Uno studio su 127 atleti professionisti mostra che il test piu usato per decidere il rientro allo sport — il confronto di forza fra le due gambe — non predice bene chi si reinfortunera. Una scala che misura quanto l'atleta si sente psicologicamente pronto, invece, si collega molto piu chiaramente alle sue prestazioni fisiche.", "Il campione degli atleti che si sono davvero reinfortunati e piccolo (32 casi): un segnale forte, ma da confermare su numeri piu ampi."], "paz": ["Dopo l'intervento al crociato, sentirsi pronti conta quanto essere forti", "Molti chirurghi decidono se un atleta puo tornare a giocare misurando la forza delle due gambe. Uno studio su 127 atleti professionisti mostra che questo test da solo non basta a prevedere chi si fara male di nuovo.", "Una valutazione di quanto l'atleta si senta psicologicamente pronto sembra un'informazione altrettanto importante. Lo studio riguarda atleti professionisti: nello sport amatoriale il messaggio di fondo — la mente conta quanto il corpo — resta comunque utile."], "kw": "rientro sport crociato, test psicologico ACL-RSI"}, "5": {"prof": ["Recupero di forza del quadricipite e cammino: due traiettorie diverse a un anno", "59 pazienti, due profili di recupero della forza post-LCA: il gruppo con recupero minore mantiene flessione e momento estensorio del ginocchio piu bassi durante il cammino fino a 12 mesi; anche il gruppo con recupero maggiore non si normalizza del tutto verso i controlli sani.", "Campione moderato (59 pazienti, due sottogruppi piu piccoli); il legame con un esito clinico duro come l'artrosi non e ancora dimostrato in questo studio."], "mix": ["Recuperare piu forza dopo il crociato cambia anche il modo di camminare", "In uno studio su 59 pazienti seguiti per un anno dopo la ricostruzione del crociato, chi recupera meno forza del muscolo quadricipite continua a camminare in modo diverso rispetto a chi ne recupera di piu — un pattern legato, in altri studi, al rischio di artrosi futura.", "Anche chi recupera bene la forza non torna a camminare esattamente come prima dell'infortunio: un argomento per non fermare la riabilitazione al solo recupero della forza muscolare."], "paz": ["Dopo l'intervento al crociato, riguadagnare forza nella coscia aiuta anche a camminare meglio", "Uno studio ha seguito 59 persone per un anno dopo l'intervento al legamento crociato, misurando sia la forza del muscolo davanti alla coscia sia il modo di camminare.", "Chi recupera meno forza cammina in modo un po' diverso ancora a un anno dall'intervento. Anche chi recupera bene non torna esattamente come prima: la riabilitazione conta, e vale la pena seguirla con costanza anche dopo i primi mesi."], "kw": "forza quadricipite dopo LCA, riabilitazione cammino"}, "6": {"prof": ["Il fenotipo funzionale del ginocchio predice l'artrosi meglio del solo HKA", "Coorte coreana, 764 ginocchia, oltre 10 anni: tre combinazioni di angolo femorale e tibiale (non il solo HKA) aumentano il rischio di progressione artrosica fino a 7 volte rispetto al fenotipo neutro (OR aggiustati 3,10-7,50).", "Sottogruppi disuguali, alcuni piccoli (20 ginocchia): intervalli di confidenza ampi nei gruppi minori; nessun dato su esiti clinici riferiti dal paziente."], "mix": ["Non basta guardare l'asse della gamba per prevedere l'artrosi del ginocchio", "Uno studio coreano ha seguito 764 ginocchia per oltre dieci anni, scomponendo l'allineamento della gamba nei suoi due componenti — femore e tibia — invece di guardare solo l'angolo complessivo.", "Alcune combinazioni specifiche di questi due angoli aumentano molto il rischio di artrosi, anche quando l'angolo complessivo sembrerebbe normale: un dato utile per chi pianifica interventi di correzione dell'asse della gamba."], "paz": ["Anche una gamba che sembra dritta puo nascondere un rischio di artrosi", "Uno studio ha seguito piu di 700 ginocchia per oltre dieci anni, guardando non solo se la gamba e dritta o storta nel complesso, ma come sono orientati separatamente femore e tibia.", "Certe combinazioni aumentano il rischio che l'artrosi peggiori nel tempo, anche quando l'asse complessivo della gamba sembra normale — un'informazione che il chirurgo puo usare per pianificare al meglio un eventuale intervento di correzione."], "kw": "allineamento ginocchio artrosi, osteotomia pianificazione"}, "7": {"prof": ["Protesi robotica: il vantaggio precoce e piu marcato per i chirurghi junior", "430 protesi (221 robot-assistite, 209 manuali): KOOS JR piu alto col robot a 3 mesi (+4,71 punti; IC 95% 2,35-7,08) ma non a 12 mesi (+0,89; p=0,461); beneficio maggiore nei chirurghi junior (+6,48 punti), che raggiungono risultati comparabili ai senior.", "Analisi sull'esperienza del chirurgo esplorativa e post hoc, non pre-pianificata; sistema robotico non specificato nell'abstract."], "mix": ["Con il robot, un chirurgo alle prime armi ottiene risultati simili a uno esperto", "Uno studio su 430 protesi di ginocchio confronta la tecnica robot-assistita con quella manuale, guardando anche all'esperienza del chirurgo. Il vantaggio del robot nei primi mesi e piu marcato proprio per i chirurghi meno esperti.", "A un anno di distanza, i risultati fra tecnica robotica e manuale si equivalgono: il beneficio del robot, quando c'e, si vede soprattutto nel recupero piu rapido nei primi mesi."], "paz": ["La protesi robotica puo aiutare soprattutto quando il chirurgo e alle prime esperienze", "In uno studio su 430 protesi di ginocchio, chi e stato operato con l'assistenza del robot ha recuperato un po' piu velocemente nei primi tre mesi, soprattutto quando l'intervento e stato eseguito da un chirurgo con meno anni di esperienza.", "A un anno di distanza il risultato finale e simile con o senza robot: la tecnologia sembra aiutare di piu a livellare il punto di partenza che a cambiare il traguardo finale."], "kw": "protesi ginocchio robot, chirurgo esperienza risultati"}, "8": {"prof": ["Semaglutide o tirzepatide prima della protesi: nessun segnale di differenza", "830 pazienti diabetici, propensity-matched: nessuna differenza a 90/180 giorni su complicanze mediche (OR 1,122) o chirurgiche (OR 1,632); intervalli ampi sui singoli eventi (infezione del sito chirurgico OR 1,726; IC 95% 0,782-3,810).", "Database amministrativo, diagnosi per codice; eventi rari con intervalli di confidenza larghi che non escludono differenze clinicamente rilevanti fra i due farmaci."], "mix": ["Due farmaci per il diabete a confronto prima della protesi di ginocchio", "Semaglutide e tirzepatide sono due farmaci sempre piu usati nei pazienti diabetici, anche prima di un intervento di protesi. Uno studio su oltre 800 pazienti abbinati per caratteristiche simili non trova differenze rilevanti fra i due farmaci sulla sicurezza dell'intervento.", "Alcuni eventi rari, come l'infezione della ferita chirurgica, restano stimati con margini di incertezza ampi: il messaggio pratico e che nessuno dei due farmaci sembra da preferire per motivi di sicurezza chirurgica, ma serve cautela sui numeri piu piccoli."], "paz": ["Se prendi un farmaco per il diabete prima della protesi di ginocchio, quale scegliere?", "Due farmaci moderni per il diabete, sempre piu diffusi, sono stati confrontati in oltre 800 pazienti che si sono sottoposti a una protesi di ginocchio.", "Non sono emerse differenze importanti di sicurezza fra i due farmaci nel periodo intorno all'intervento. E un'informazione utile da condividere con il proprio diabetologo e chirurgo, non un motivo per cambiare terapia da soli."], "kw": "diabete protesi ginocchio, semaglutide tirzepatide"}, "9": {"prof": ["Le protesi di sutura meniscale non sono tutte uguali per gli eventi avversi", "Editoriale su un'analisi del database FDA MAUDE: le ancore rigide senza nodo esposto sulla superficie del menisco risultano associate a meno segnalazioni di eventi avversi rispetto ai dispositivi a tutto-sutura o con nodo esposto.", "Editoriale di livello V, senza analisi statistica propria ne correzione per il volume di impianti per categoria; nomi dei dispositivi non riportati."], "mix": ["Anche il tipo di ancoretta usata per riparare il menisco puo fare la differenza", "Un commento editoriale riassume i dati di un database di sicurezza statunitense sui dispositivi usati per riparare il menisco per via artroscopica, distinguendo tre tipi di costrutto.", "I dispositivi con un'ancora rigida che non lascia un nodo a contatto con il menisco risultano associati a meno segnalazioni di problemi. Il dato non identifica marche specifiche e non tiene conto di quanti dispositivi di ciascun tipo siano stati impiantati in totale."], "paz": ["Anche il tipo di punto usato per riparare il menisco puo contare", "Quando si ripara il menisco in artroscopia, si usano diversi tipi di dispositivi per fissare la sutura. Un commento scientifico riassume i dati di sicurezza raccolti negli Stati Uniti su questi dispositivi.", "Alcuni tipi di fissaggio sembrano associarsi a meno problemi segnalati di altri, anche se il dato non permette di indicare una marca precisa. E un promemoria che i dettagli tecnici dell'intervento contano, piu che un motivo di allarme."], "kw": "sutura menisco dispositivi, riparazione meniscale sicurezza"}};
var ARTICLES=[{n:1,mono:"m-gray",dot:"green",sec:"res",j:"Orthopaedic Journal of Sports Medicine",h:"Tendine quadricipite o hamstring: la non-differenza regge alla prova",v:"Rianalisi di fragilita di 8 RCT (562 pazienti): gli esiti comparabili fra i due innesti nel LCA sono statisticamente robusti, non un artefatto della perdita al follow-up.",ax:"Tseng, Fu, Lo et al.",date:"set 2026",meta:"revisione sistematica di RCT, indice di fragilita inversa continua · [I]",pmid:'42724261',doi:'10.1177/23259671261479032',journal:"Orthopaedic Journal of Sports Medicine",authors:"Tseng TH, Fu SH, Lo YC, Chen CL, Chiang H",design:"Revisione sistematica secondo PRISMA (PubMed, Embase, Cochrane Library, dall'inizio delle banche dati ad aprile 2026) di RCT di livello 1 che confrontano innesto di tendine hamstring (HT) e tendine quadricipitale (QT) nella ricostruzione primaria del LCA nell'adulto, con almeno un esito continuo non significativo riportato con statistiche sufficienti per calcolare l'indice di fragilita continua inversa (rCFI): quanti pazienti dovrebbero cambiare risultato, nella simulazione, prima che una differenza non significativa diventi significativa. L'rCFI e stato confrontato con la perdita al follow-up di ciascuno studio.",pop:"8 RCT, 562 pazienti allocati, 482 disponibili al punto di follow-up usato per l'analisi primaria (80 persi al follow-up).",results:"rCFI medio 17,4±7,3 e quoziente di fragilita inversa continuo medio 0,296±0,069. Tutti gli esiti primari continui non significativi idonei avevano un rCFI superiore alla corrispondente perdita al follow-up dello studio; l'analisi di sensibilita (20 semi di simulazione) ha confermato la stabilita delle stime. Su 21 esiti secondari idonei, 19 avevano un rCFI superiore alla perdita al follow-up.",concl:"Gli autori concludono che gli esiti continui non significativi degli RCT che confrontano HT e QT nella ricostruzione del LCA sono statisticamente robusti, a sostegno della stabilita dell'evidenza randomizzata su esiti comparabili a breve termine fra i due innesti.",limits:"Analizza solo esiti continui non significativi: non dice nulla su esiti binari (fallimento, revisione) ne su follow-up a lungo termine · nessuno degli 8 RCT include il rinforzo laterale (LET) che tu esegui su ogni paziente: la robustezza riguarda l'innesto isolato, non la tua combinazione con il LET · rCFI e una misura di stabilita statistica, non di rilevanza clinica della differenza (che qui e comunque assente).",perte:"Rafforza, sul piano metodologico, la base su cui poggia la scelta del tendine quadricipitale al posto dell'hamstring: la letteratura che dice «esiti comparabili a breve termine» non e un artefatto statistico fragile. Non tocca pero la domanda che piu ti riguarda — se il beneficio del LET dimostrato su hamstring si trasferisca al tuo innesto rigido — che resta aperta nella tensione T1a."},{n:2,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"La lassita articolare generalizzata pesa dopo la ricostruzione del LCA",v:"Meta-analisi di 13 studi (3905 pazienti): piu lassita residua e piu Lachman/pivot shift positivi in chi ha lassita generalizzata, senza una differenza certa nel fallimento dell'innesto.",ax:"Za, Papalia, Caria et al.",date:"set 2026",meta:"revisione sistematica e meta-analisi, 13 studi/3905 pazienti · [III]",pmid:'42726919',doi:'10.1002/ksa.70598',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Za P, Papalia GF, Caria C, Minelli M, Basciani S, Vasta S",design:"Revisione sistematica e meta-analisi PRISMA 2020 su studi che riportano PROM, lassita residua e tasso di reinfortunio/fallimento dell'innesto in pazienti con lassita articolare generalizzata (GJL) sottoposti a ricostruzione primaria del LCA, confrontati quando disponibile con pazienti senza GJL. Valutazione metodologica con MINORS.",pop:"13 studi, 3905 pazienti (55% uomini, 45% donne), eta media 27,5 anni (23,4-29,7), follow-up medio 41,1 mesi (12-96).",results:"IKDC piu basso nel gruppo GJL (85,2±11,6 contro 87,7±10,1 nel non-GJL; differenza media -3,27; p=0,05). Lysholm piu basso nel gruppo GJL (88,5±6,3 contro 93,5±5,8; p=0,005). Lachman positivo (OR 2,62; p<0,0001) e pivot shift positivo (OR 2,25; p=0,0007) piu frequenti nel gruppo GJL. Fallimento della ricostruzione 9,2% nel gruppo GJL contro 6,1% nel non-GJL, senza significativita statistica (OR 3,15; p=0,07; intervallo di confidenza non riportato nell'abstract).",concl:"Gli autori concludono che i pazienti con GJL hanno una maggiore lassita residua dopo la ricostruzione del LCA rispetto ai non-GJL, con esiti clinici eterogenei, mentre non emerge una differenza statisticamente significativa nel tasso di fallimento dell'innesto.",limits:"Livello III, eterogeneita fra studi non quantificata nell'abstract · l'OR di 3,15 sul fallimento e riportato senza intervallo di confidenza: con p=0,07 al limite della significativita, non si puo escludere ne un rischio sostanzialmente piu alto ne l'assenza di un vero effetto · GJL definita in modo variabile fra gli studi inclusi (criteri di Beighton non uniformi).",perte:"Un profilo di rischio da conoscere prima di operare pazienti con lassita generalizzata, indipendentemente dall'innesto: piu lassita residua attesa e piu segni clinici positivi al controllo, anche se il rischio di dover rifare l'intervento resta statisticamente incerto. Non specifico al tendine quadricipitale ne al LET."},{n:3,mono:"m-gray",dot:"green",sec:"res",j:"Journal of ISAKOS",h:"Operare il LCA entro tre mesi riduce le lesioni meniscali associate",v:"Revisione sistematica di 11 studi (oltre 9500 pazienti): il ritardo oltre tre mesi si associa a piu lesioni del menisco mediale; sui punteggi funzionali nessun vantaggio chiaro per nessuna delle due scelte.",ax:"Heder Ternell, Nilsson, Cristiani et al.",date:"set 2026",meta:"revisione sistematica, 11 studi osservazionali/9500+ pazienti · [III]",pmid:'42727886',doi:'10.1016/j.jisako.2026.101215',journal:"Journal of ISAKOS",authors:"Heder Ternell K, Nilsson E, Cristiani R, Stalman A, Horvath A, Hammarstrand C",design:"Revisione sistematica (PubMed, Embase, Web of Science, CINAHL, Cochrane Library, ricerca al 10 luglio 2025; registrazione PROSPERO CRD420251104801) su studi clinici in inglese dal 2000 che confrontano ricostruzione del LCA precoce (entro 3 mesi dall'infortunio) e ritardata, in pazienti dai 16 anni, su patologia intra-articolare associata, esiti riferiti dal paziente, lassita, revisione, rientro allo sport e artrosi. Sintesi narrativa per l'eterogeneita di disegno e definizioni di timing.",pop:"11 studi osservazionali, oltre 9500 pazienti in totale.",results:"Lesione meniscale piu frequente nel gruppo ritardato rispetto al precoce (59,6% contro 49,5%), soprattutto a carico del menisco mediale. Lesioni condrali riportate con frequenza simile fra ritardato e precoce (20,4% contro 18,6%). I punteggi riferiti dal paziente (KOOS, IKDC, Tegner, Lysholm) sono riportati in modo incoerente e non mostrano un vantaggio consistente per il timing precoce ne per quello ritardato. Nessuno studio incluso riporta misure KT-1000, rientro allo sport o esiti di artrosi; i dati di revisione sono scarsi.",concl:"Gli autori concludono che la ricostruzione entro tre mesi dall'infortunio si associa a una minore prevalenza di lesioni meniscali rispetto alla ricostruzione ritardata, mentre non emergono differenze chiare su lesioni condrali o punteggi riferiti dal paziente; l'evidenza su lassita, revisione, rientro allo sport e artrosi resta insufficiente.",limits:"Livello III, disegno osservazionale in tutti gli studi inclusi: il timing non e randomizzato, e i pazienti operati piu tardi possono differire per motivi che spiegano sia il ritardo sia il danno meniscale (confondimento per indicazione) · sintesi narrativa, nessuna stima aggregata con intervallo di confidenza · nessun dato su rientro allo sport, lassita strumentale o artrosi.",perte:"Un argomento in piu, sul fronte del menisco, per non prolungare inutilmente l'attesa prima della ricostruzione quando la riparazione meniscale associata e probabile: aggiunge un dato quantitativo alla decisione fra ricostruzione precoce e riabilitazione iniziale con eventuale intervento ritardato. Non riguarda direttamente T2b (l'estrusione, non il timing, resta il determinante piu forte per la progressione cartilaginea gia dimostrato), ma tocca un esito diverso — la prevalenza della lesione meniscale al momento dell'intervento."},{n:4,mono:"m-gray",dot:"green",sec:"res",j:"Sports Health",h:"Nel rientro allo sport la prontezza psicologica conta quanto i test",v:"127 atleti professionisti: l'indice di simmetria di forza (LSI) discrimina poco il reinfortunio; le performance assolute di hop test correlano fortemente con la scala di prontezza psicologica ACL-RSI.",ax:"Rahimi Khoygani, Esmaeili",date:"set 2026",meta:"coorte prospettica con caso-controllo annidato, 127 atleti · [II]",pmid:'42725577',doi:'10.1177/19417381261480055',journal:"Sports Health",authors:"Rahimi Khoygani M, Esmaeili H",design:"Coorte prospettica (2021-2024) di atleti professionisti sottoposti a batteria standardizzata di 10 hop test e 3 questionari riferiti dal paziente incluso l'ACL-RSI dopo ricostruzione del LCA, con reinfortunio tracciato per 3 anni. Analisi caso-controllo annidata: 32 atleti con reinfortunio da rottura dell'innesto non da contatto, abbinati a 32 controlli senza reinfortunio, confrontati su performance assoluta ai test, LSI e punteggi dei questionari.",pop:"127 atleti professionisti testati; sottostudio caso-controllo su 32 casi di reinfortunio e 32 controlli abbinati.",results:"7 dei 10 hop test mostrano differenze laterali significative in performance assoluta (p=0,01-0,04) fra chi si reinfortuna e chi no. L'LSI ha valore discriminante limitato: un solo risultato significativo, e solo nelle atlete donne (p=0,03). Correlazioni forti e significative fra performance di hop test e punteggio ACL-RSI (r=0,43-0,73; p<0,05).",concl:"Gli autori concludono che le misure di performance assoluta ai test di salto, combinate con la valutazione della prontezza psicologica, discriminano il rischio di reinfortunio meglio del solo indice di simmetria (LSI), e propongono l'ACL-RSI come strumento per stabilire quando un atleta e pronto per test funzionali ad alta intensita.",limits:"Livello II, ma disegno con caso-controllo annidato su un campione ridotto (32 coppie): le correlazioni, per quanto forti, provengono da un numero limitato di eventi di reinfortunio · popolazione di atleti professionisti, trasferibilita a pazienti non agonisti da verificare · nessun dettaglio nell'abstract sul tipo di innesto utilizzato.",perte:"Alimenta direttamente la tensione T3: un'ulteriore conferma che il criterio di rientro basato sulla sola simmetria di forza (LSI) e insufficiente, e che una misura di prontezza psicologica standardizzata (ACL-RSI) aggiunge informazione reale sul rischio, non solo una sensazione soggettiva da colloquio."},{n:5,mono:"m-gray",dot:"green",sec:"res",j:"Sports Health",h:"Chi recupera meno forza del quadricipite cammina peggio anche a un anno",v:"59 pazienti seguiti un anno dopo il LCA: chi recupera meno forza mantiene un'alterazione della meccanica del cammino legata al rischio di artrosi; anche chi recupera meglio non si normalizza del tutto.",ax:"Lemus, Buttner, Arbeeva et al.",date:"set 2026",meta:"coorte prospettica, 59 pazienti · [II]",pmid:'42725538',doi:'10.1177/19417381261479680',journal:"Sports Health",authors:"Lemus SA, Buttner C, Arbeeva L, Lisee C, Favoreto N, Creighton RA, Kamath GM, Spang JT, Ingersoll CD, Tayne S, Hart JM, Blackburn JT, Pietrosimone B",design:"Coorte prospettica di pazienti con lesione primaria del LCA, abbinati per sesso, eta e BMI a controlli non infortunati. Forza del quadricipite misurata prima dell'intervento e a 4, 6 e 12 mesi dopo la ricostruzione; biomeccanica del cammino (forza di reazione al terreno verticale vGRF, angolo di flessione del ginocchio KFA, momento estensorio KEM, momento adduttorio KAM) misurata agli stessi tre punti temporali. Modellazione delle traiettorie di gruppo per identificare profili di recupero della forza, confrontati con modelli a effetti misti funzionali.",pop:"62 pazienti arruolati, 59 idonei e abbinati a controlli sani; due traiettorie di recupero della forza identificate (31 con recupero minore, 28 con recupero maggiore).",results:"Entrambi i gruppi operati mostrano vGRF piu bassa in fase di appoggio iniziale rispetto ai controlli (differenza massima -0,15 peso corporeo). Il gruppo con recupero di forza minore mostra, rispetto al gruppo con recupero maggiore, KFA piu basso (-1,85° e -2,18° a 6 e 12 mesi) e KEM piu basso (0,006 peso×altezza a 4 e 6 mesi); solo il gruppo con recupero minore ha KAM significativamente piu basso dei controlli (0,006-0,007 peso×altezza a 4, 6 e 12 mesi).",concl:"Gli autori concludono che due traiettorie distinte di recupero della forza del quadricipite emergono nel primo anno dopo la ricostruzione del LCA, e che il gruppo con recupero minore mantiene una biomeccanica del cammino piu alterata; anche il gruppo con recupero maggiore non normalizza completamente il cammino rispetto ai controlli sani.",limits:"Livello II, campione moderato (59 pazienti) suddiviso in due sottogruppi ancora piu piccoli · nessun dato nell'abstract sul tipo di innesto utilizzato · le differenze biomeccaniche, per quanto statisticamente significative, non sono ancora collegate in questo studio a un esito clinico duro come l'artrosi.",perte:"Aggiunge alla tensione T3 una dimensione temporale concreta: la traiettoria di recupero della forza nel primo anno, non solo il valore di simmetria a un singolo controllo, si associa ad alterazioni del cammino potenzialmente rilevanti per il rischio di artrosi post-traumatica a lungo termine — un argomento per interventi riabilitativi mirati oltre il solo rinforzo muscolare."},{n:6,mono:"m-gray",dot:"green",sec:"res",j:"Knee Surgery, Sports Traumatology, Arthroscopy",h:"Non solo l'asse: il fenotipo funzionale del ginocchio predice l'artrosi a 10 anni",v:"764 ginocchia seguite oltre 10 anni: alcune combinazioni di angoli femorali e tibiali, non solo l'asse meccanico complessivo, aumentano fino a 7 volte il rischio di progressione artrosica.",ax:"Song, Lee, Park",date:"set 2026",meta:"coorte retrospettiva longitudinale, 388 pazienti/764 ginocchia · [III]",pmid:'42726921',doi:'10.1002/ksa.70591',journal:"Knee Surgery, Sports Traumatology, Arthroscopy",authors:"Song SJ, Lee HB, Park CH",design:"Studio retrospettivo longitudinale su pazienti con ginocchio sano o artrosi precoce (Kellgren-Lawrence ≤1) al basale e almeno 10 anni di follow-up. Fenotipi funzionali del ginocchio (FKP) classificati in base ad angolo hip-knee-ankle (HKA), angolo meccanico femorale (FMA) e angolo meccanico tibiale (TMA) misurati su ortoradiografie; 72 combinazioni identificate, 15 con almeno 20 ginocchia selezionate per l'analisi. Progressione artrosica definita come aumento di almeno un grado Kellgren-Lawrence. Regressione logistica multivariata con equazioni di stima generalizzata.",pop:"388 pazienti, 764 ginocchia; 511 ginocchia nei 15 fenotipi analizzati; follow-up minimo 10 anni.",results:"Progressione artrosica nel gruppo di riferimento neutro: 52,4% (44/84). Tre fenotipi con progressione significativamente piu alta: varo-varo-neutro 88,9% (32/36; OR 7,27; IC 95% 2,36-22,38; p<0,001), valgo-neutro-valgo 84,6% (22/26; OR 5,00; IC 95% 1,59-15,76; p=0,005), neutro-varo-valgo 75,0% (24/32; OR 2,73; IC 95% 1,10-6,76; p=0,035). Confermati in analisi multivariata aggiustata (OR aggiustati 6,54; 7,50; 3,10 rispettivamente).",concl:"Gli autori concludono che specifici fenotipi funzionali del ginocchio, definiti dalla combinazione di allineamento femorale e tibiale, si associano a un rischio significativamente piu alto di progressione artrosica rispetto al fenotipo neutro, indicando che non e solo l'allineamento complessivo dell'arto a contare, ma la combinazione dei pattern femorale e tibiale.",limits:"Livello III, studio retrospettivo su un solo centro coreano · sottogruppi di dimensioni disuguali (da 20 a oltre 80 ginocchia), con intervalli di confidenza ampi nei gruppi piu piccoli (fino a 30) · nessuna correlazione con esiti clinici riferiti dal paziente, solo con la progressione radiografica.",perte:"Un argomento per il planning delle osteotomie correttive: il bersaglio di correzione forse non dovrebbe guardare solo all'asse meccanico complessivo (HKA), ma alla combinazione di angolo femorale e tibiale — coerente con il principio, gia visto in T2b, che il carico degenerativo dipende da piu di un singolo numero riassuntivo."},{n:7,mono:"m-gray",dot:"green",sec:"res",j:"Journal of Robotic Surgery",h:"La protesi robotica aiuta soprattutto i chirurghi meno esperti",v:"430 protesi totali: il vantaggio precoce del robot sui punteggi funzionali sparisce a un anno, ma a 3 mesi e piu marcato per i chirurghi junior, che raggiungono risultati simili ai senior.",ax:"Zhang, Mao, Wu et al.",date:"set 2026",meta:"coorte comparativa retrospettiva, 430 pazienti · [III]",pmid:'42726345',doi:'10.1007/s11701-026-03944-y',journal:"Journal of Robotic Surgery",authors:"Zhang J, Mao X, Wu X, Yang D, Wang J, Dong W, She Z, Zhang X, Yuan H",design:"Coorte comparativa retrospettiva su protesi totale di ginocchio robot-assistita (R-TKA, n=221) e manuale (M-TKA, n=209), con KOOS JR valutato prima dell'intervento e a 3, 6 e 12 mesi. Modelli lineari a effetti misti con misure ripetute e aggiustamento per covariate; raggiungimento di MDC/MCID/SCB/PASS confrontato fra gruppi con correzione di Holm per confronti multipli. Analisi esplorativa post hoc sull'esperienza del chirurgo.",pop:"430 pazienti (221 R-TKA, 209 M-TKA).",results:"A 3 mesi, KOOS JR aggiustato piu alto nel gruppo R-TKA (differenza 4,71 punti; IC 95% 2,35-7,08; p<0,001); differenza ridotta a 3,13 punti a 6 mesi (p=0,010) e non significativa a 12 mesi (0,89 punti; p=0,461). A 3 mesi tassi piu alti di raggiungimento di MDC, MCID e SCB nel gruppo R-TKA (tutti p≤0,05 dopo correzione di Holm). Nell'analisi post hoc, il beneficio maggiore del robot a 3 mesi si osserva nei chirurghi junior (+6,48 punti; p=0,003 dopo correzione di Holm), che con il robot raggiungono risultati comparabili ai chirurghi senior.",concl:"Gli autori concludono che la protesi robot-assistita si associa a esiti riferiti dal paziente piu favorevoli nel primo periodo postoperatorio, con un beneficio precoce maggiore per i chirurghi meno esperti, che potrebbe attenuare le differenze di risultato legate all'esperienza chirurgica.",limits:"Livello III, studio retrospettivo, sistema robotico non specificato nell'abstract (non necessariamente VELYS) · l'analisi sull'esperienza del chirurgo e esplorativa post hoc, non pre-pianificata · il vantaggio funzionale sparisce a 12 mesi: il beneficio del robot, quando c'e, e nella fase precoce.",perte:"Un dato pratico sulla piattaforma robotica che usi: il vantaggio piu solido non e nel risultato finale a un anno (dove converge con la tecnica manuale), ma nella fase precoce e, potenzialmente, nell'appianare le differenze fra chirurghi con esperienza diversa — utile nel colloquio con pazienti operati da equipe miste per esperienza."},{n:8,mono:"m-gray",dot:"green",sec:"res",j:"The Knee",h:"Semaglutide o tirzepatide prima della protesi: stessa sicurezza a breve termine",v:"830 pazienti diabetici abbinati per propensione: nessuna differenza fra i due farmaci su complicanze mediche, chirurgiche o infezione periprotesica dopo protesi di ginocchio, ma con intervalli ampi sui singoli eventi.",ax:"Wu KA, Choudhury, Wu JA et al.",date:"set 2026",meta:"coorte retrospettiva propensity-matched, 830 pazienti · [III]",pmid:'42727208',doi:'10.1016/j.knee.2026.104639',journal:"The Knee",authors:"Wu KA, Choudhury A, Wu JA, Shenoy DA, Song J, Mai E, Dhanjani S, Shatkin M, Wellman SS, Seyler TM, Moucha CS, Hayden BL",design:"Coorte retrospettiva su database TriNetX. Adulti con diabete di tipo 2 sottoposti a protesi totale di ginocchio primaria (giugno 2022-dicembre 2024) con prescrizione attiva di semaglutide o tirzepatide nei 90 giorni preoperatori, abbinati 1:1 per propensione su eta, sesso, etnia, BMI, HbA1c, carico di comorbidita e farmaci antidiabetici concomitanti. Esiti a 90 e 180 giorni: complicanze mediche e chirurgiche, utilizzo sanitario. Odds ratio con regressione logistica.",pop:"415 coppie abbinate (830 pazienti totali) dopo propensity score matching.",results:"Nessuna differenza a 90 giorni per complicanze mediche (OR 1,122; IC 95% 0,736-1,710; p=0,591) ne a 180 giorni per complicanze chirurgiche (OR 1,632; IC 95% 0,845-3,152; p=0,141) fra semaglutide e tirzepatide. Eventi singoli statisticamente simili, ma con intervalli ampi: infezione del sito chirurgico OR 1,726 (IC 95% 0,782-3,810; p=0,172) — un intervallo che non esclude un rischio quasi quadruplicato con uno dei due farmaci; lesione renale acuta OR 0,867 (IC 95% 0,417-1,801); infezione urinaria OR 1,562 (IC 95% 0,863-2,827). Visite in pronto soccorso e riammissioni comparabili a 90 e 180 giorni.",concl:"Gli autori concludono che, in una grande coorte nazionale abbinata per propensione, semaglutide e tirzepatide mostrano profili di sicurezza e utilizzo sanitario a breve termine simili in pazienti diabetici sottoposti a protesi totale di ginocchio, a sostegno dell'uso perioperatorio continuato di entrambi gli agenti.",limits:"Livello III, database amministrativo: diagnosi e prescrizioni per codice, non verificate clinicamente · diversi esiti (infezione periprotesica, revisione, mortalita) hanno pochi eventi in entrambi i gruppi: gli intervalli di confidenza restano larghi e non escludono differenze clinicamente rilevanti in un senso o nell'altro · nessun confronto con pazienti diabetici senza terapia GLP-1/GIP.",perte:"Rilevante per il colloquio perioperatorio con pazienti diabetici in terapia con questi farmaci, sempre piu frequenti prima della tua protesi VELYS: a differenza dello studio dell'8 settembre che confrontava GLP-1 RA con il non uso, qui il confronto e fra i due farmaci piu diffusi, e non emerge un motivo per preferirne uno sull'altro sul piano della sicurezza chirurgica a breve termine."},{n:9,mono:"m-gray",dot:"green",sec:"res",j:"Arthroscopy",h:"Non tutte le protesi di sutura meniscale danno gli stessi problemi",v:"Editoriale su un'analisi della banca dati di sicurezza FDA (MAUDE): le ancore rigide senza nodo sulla superficie meniscale risultano associate a meno segnalazioni di eventi avversi rispetto a quelle a tutto-sutura o con nodo esposto.",ax:"Barber FA",date:"set 2026",meta:"editoriale su un'analisi di banca dati di sicurezza, nomi dei dispositivi non riportati · [V]",pmid:'42725710',doi:'10.1002/arj.70591',journal:"Arthroscopy",authors:"Barber FA",design:"Editoriale di commento su una recente analisi delle segnalazioni di eventi avversi nel database MAUDE (Manufacturer and User Facility Device Experience) della Food and Drug Administration statunitense, relative a dispositivi per sutura meniscale all-inside, distinti in tre categorie tecniche: riparazione a tutto-sutura, ancora rigida senza nodo sulla superficie meniscale, ancora rigida con nodo sulla superficie meniscale.",pop:"Non applicabile: editoriale di commento su un'analisi di banca dati di segnalazioni, non uno studio clinico su pazienti.",results:"I sistemi di riparazione meniscale con ancora rigida e senza nodo extra-capsulare sulla superficie del menisco risultano associati a meno segnalazioni di eventi avversi rispetto sia ai dispositivi a tutto-sutura sia alle ancore rigide con nodo esposto sul menisco. L'autore segnala inoltre che alcuni produttori riportano gli eventi avversi con tempistiche molto piu lente di altri.",concl:"L'editoriale conclude che il tipo di costrutto dei dispositivi di sutura meniscale — in particolare la presenza di un nodo esposto sulla superficie del menisco — sembra associarsi a pattern diversi di eventi avversi segnalati, e invita a una lettura critica delle segnalazioni MAUDE, che non distinguono per volume di impianti.",limits:"Livello V, editoriale di commento — non uno studio primario, nessun'analisi statistica propria ne dato di incidenza corretto per il volume di impianti per categoria · i nomi dei dispositivi e dei produttori non sono riportati, quindi il dato non e attribuibile a un prodotto specifico · le segnalazioni MAUDE sono passive e soggette a sotto-segnalazione disomogenea fra produttori, come lo stesso editoriale nota.",perte:"Tocca una procedura che esegui regolarmente (sutura meniscale): un promemoria che il tipo di costrutto del dispositivo — non solo la tecnica chirurgica — puo incidere sul profilo di eventi avversi, anche se qui senza poter identificare quale sistema specifico tu utilizzi nel confronto."}];
var SUGGQ=[{"k": "kol", "n": "Tzu-Hao Tseng", "w": "National Taiwan University Hospital, Taipei (Taiwan)", "r": "Primo autore dello studio di oggi sulla rianalisi di fragilita fra innesto hamstring e tendine quadricipitale nella ricostruzione del LCA: corrispondenza tecnica diretta con la tua scelta di innesto. Primo nome taiwanese proposto, nella direzione dichiarata di allargare la rete anche al mondo orientale. Sostituisce la proposta invariata di Daniel W. Green (11 settembre)."}];
var BRIEF_TEXT="Nove lavori oggi, nessuno rosso, nessuno arancione: una giornata di conferme e affinamenti, non di scosse. Il lavoro scelto e una rianalisi di fragilita su otto RCT che confrontano l'innesto di tendine hamstring e quello di tendine quadricipitale nella ricostruzione del LCA: la conclusione «esiti comparabili a breve termine», spesso letta con sospetto quando arriva da confronti non significativi, regge alla prova statistica — non e un artefatto della perdita al follow-up. Non tocca la tua combinazione con il rinforzo laterale, ma rafforza il terreno su cui poggia la scelta del tendine quadricipitale. Sul fronte del rientro allo sport, due lavori spingono nella stessa direzione della tensione che questo sistema segue da luglio: l'indice di simmetria di forza da solo discrimina poco il reinfortunio, mentre la prontezza psicologica misurata con scale dedicate correla fortemente con le prestazioni fisiche; e chi recupera meno forza del quadricipite nel primo anno cammina in modo misurabilmente diverso, anche a distanza di dodici mesi. Sulla protesi robotica, un dato pratico: il vantaggio funzionale precoce del robot si concentra nei chirurghi meno esperti, che con l'assistenza robotica raggiungono risultati comparabili ai colleghi senior — un argomento sull'equita dei risultati fra chirurghi, piu che sulla superiorita della tecnica in se, visto che a un anno le due strade convergono. Il raccoglitore notturno non e passato anche questa notte: richiami di dispositivi, Swissmedic, congressi, societa e destino dei verdetti restano non verificati per oggi. Le ritrattazioni sono state ricontrollate a mano su tutti i 216 PMID gia citati nello storico piu i 9 di oggi: nessun nuovo esito, confermata la sola Expression of Concern gia nota dal 3 settembre.";
var BRIEF_DIALOGO=[{"chi": "A", "t": "Partiamo dal lavoro scelto oggi: una rianalisi statistica, non uno studio clinico nuovo."}, {"chi": "B", "t": "Che tipo di rianalisi?"}, {"chi": "A", "t": "Otto studi randomizzati hanno confrontato l'innesto di tendine hamstring e quello di tendine quadricipitale nel legamento crociato anteriore, trovando risultati simili. Questa rianalisi verifica se quel «simili» sia un risultato solido o fragile."}, {"chi": "B", "t": "E il verdetto?"}, {"chi": "A", "t": "Solido. L'indice di fragilita medio e ben superiore al numero di pazienti persi durante gli studi: la conclusione non cambierebbe nemmeno se qualche paziente in piu avesse avuto un esito diverso."}, {"chi": "B", "t": "Quindi per la tua pratica con il tendine quadricipitale e una buona notizia."}, {"chi": "A", "t": "Si, ma con un limite chiaro: nessuno di quegli otto studi include il rinforzo laterale che esegui su ogni paziente. Rafforza la base sull'innesto, non chiude la domanda sul LET."}, {"chi": "B", "t": "Cosa c'e sul rientro allo sport, oggi?"}, {"chi": "A", "t": "Due lavori. Il primo, su 127 atleti professionisti, mostra che il classico confronto di forza fra le due gambe predice poco chi si reinfortunera; conta di piu quanto l'atleta si senta psicologicamente pronto."}, {"chi": "B", "t": "E il secondo?"}, {"chi": "A", "t": "Segue 59 pazienti per un anno: chi recupera meno forza del quadricipite continua a camminare in modo diverso, anche dopo dodici mesi. Un argomento per non fermare la riabilitazione al solo numero di forza."}, {"chi": "B", "t": "E la protesi robotica?"}, {"chi": "A", "t": "Qui il dato interessante e chi ne beneficia di piu: nei primi tre mesi, i chirurghi meno esperti ottengono con il robot risultati vicini a quelli dei colleghi senior. A un anno, pero, le due tecniche si equivalgono."}, {"chi": "B", "t": "Quindi il robot livella piu che superare."}, {"chi": "A", "t": "Esattamente. E per finire: il raccoglitore automatico dei richiami e delle fonti esterne non e passato anche stanotte, ma ho ricontrollato a mano tutte le citazioni storiche del sistema — nessuna nuova ritrattazione."}];
